 */

import Handlebars from 'handlebars';
import type { ExecutionContext } from './context-manager';

// ============================================================================
// Template Engine Class
// ============================================================================

export class TemplateEngine {
  private handlebars: typeof Handlebars;

  constructor() {
    this.handlebars = Handlebars.create();
    this.registerHelpers();
  }

  /**
   * Render template with context variables
   */
  render(template: string, context: ExecutionContext): string {
    try {
      const compiled = this.handlebars.compile(template);
      const variables = this.buildVariableObject(context);
      return compiled(variables);
    } catch (error) {
      throw new TemplateRenderError(
        `Failed to render template: ${error instanceof Error ? error.message : 'Unknown error'}`,
        { template, error }
      );
    }
  }

  /**
   * Validate template syntax
   */
  validate(template: string): ValidationResult {
    try {
      this.handlebars.compile(template);
      return { valid: true, errors: [] };
    } catch (error) {
      return {
        valid: false,
        errors: [error instanceof Error ? error.message : 'Unknown error']
      };
    }
  }

  /**
   * Extract variable names from template
   */
  extractVariables(template: string): string[] {
    const variables = new Set<string>();

    try {
      const ast = Handlebars.parse(template);
      this.walkAST(ast, (node: any) => {
        if (node.type === 'PathExpression') {
          variables.add(node.original);
        }
      });
    } catch (error) {
      console.error('Failed to extract variables:', error);
    }

    return Array.from(variables);
  }

  /**
   * Register custom Handlebars helpers
   */
  private registerHelpers(): void {
    // String helpers
    this.handlebars.registerHelper('uppercase', (str: string) => 
      str ? str.toUpperCase() : ''
    );

    this.handlebars.registerHelper('lowercase', (str: string) => 
      str ? str.toLowerCase() : ''
    );

    this.handlebars.registerHelper('truncate', (str: string, length: number) => 
      str && str.length > length ? str.substring(0, length) + '...' : str
    );

    this.handlebars.registerHelper('capitalize', (str: string) =>
      str ? str.charAt(0).toUpperCase() + str.slice(1) : ''
    );

    // Array helpers
    this.handlebars.registerHelper('join', (arr: any[], separator: string) => 
      Array.isArray(arr) ? arr.join(separator || ', ') : ''
    );

    this.handlebars.registerHelper('first', (arr: any[]) => 
      Array.isArray(arr) && arr.length > 0 ? arr[0] : null
    );

    this.handlebars.registerHelper('last', (arr: any[]) => 
      Array.isArray(arr) && arr.length > 0 ? arr[arr.length - 1] : null
    );

    this.handlebars.registerHelper('length', (arr: any[]) =>
      Array.isArray(arr) ? arr.length : 0
    );

    // Conditional helpers
    this.handlebars.registerHelper('eq', (a: any, b: any) => a === b);
    this.handlebars.registerHelper('ne', (a: any, b: any) => a !== b);
    this.handlebars.registerHelper('gt', (a: number, b: number) => a > b);
    this.handlebars.registerHelper('lt', (a: number, b: number) => a < b);
    this.handlebars.registerHelper('gte', (a: number, b: number) => a >= b);
    this.handlebars.registerHelper('lte', (a: number, b: number) => a <= b);
    this.handlebars.registerHelper('and', (...args: any[]) => {
      // Remove Handlebars options object
      args.pop();
      return args.every(Boolean);
    });
    this.handlebars.registerHelper('or', (...args: any[]) => {
      // Remove Handlebars options object
      args.pop();
      return args.some(Boolean);
    });
    this.handlebars.registerHelper('not', (value: any) => !value);

    // Number helpers
    this.handlebars.registerHelper('add', (a: number, b: number) => a + b);
    this.handlebars.registerHelper('subtract', (a: number, b: number) => a - b);
    this.handlebars.registerHelper('multiply', (a: number, b: number) => a * b);
    this.handlebars.registerHelper('divide', (a: number, b: number) => b !== 0 ? a / b : 0);
    this.handlebars.registerHelper('round', (num: number, decimals: number = 0) => 
      Number(num.toFixed(decimals))
    );

    // Date helpers
    this.handlebars.registerHelper('formatDate', (date: Date | string, format: string = 'YYYY-MM-DD') => {
      try {
        const d = typeof date === 'string' ? new Date(date) : date;
        // Simple date formatting (in production, use date-fns or similar)
        return d.toISOString().split('T')[0];
      } catch {
        return '';
      }
    });

    // JSON helpers
    this.handlebars.registerHelper('json', (obj: any, pretty: boolean = false) => {
      try {
        return JSON.stringify(obj, null, pretty ? 2 : 0);
      } catch {
        return '';
      }
    });

    // Default value helper
    this.handlebars.registerHelper('default', (value: any, defaultValue: any) =>
      value !== null && value !== undefined ? value : defaultValue
    );
  }

  /**
   * Build variable object from execution context
   */
  private buildVariableObject(context: ExecutionContext): Record<string, any> {
    const variables: Record<string, any> = {
      input: context.input,
      ...Object.fromEntries(context.variables)
    };

    // Add step results
    for (const [stepId, result] of context.stepResults) {
      variables[stepId] = result.output;
    }

    // Add metadata
    variables.context = {
      stepCount: context.stepResults.size,
      duration: Date.now() - context.startTime,
      traceId: context.traceId
    };

    return variables;
  }

  /**
   * Walk AST and execute callback for each node
   */
  private walkAST(node: any, callback: (node: any) => void): void {
    if (!node) return;

    callback(node);

    if (node.body) {
      if (Array.isArray(node.body)) {
        node.body.forEach((child: any) => this.walkAST(child, callback));
      } else {
        this.walkAST(node.body, callback);
      }
    }

    if (node.program) {
      this.walkAST(node.program, callback);
    }

    if (node.inverse) {
      this.walkAST(node.inverse, callback);
    }

    if (node.params) {
      node.params.forEach((param: any) => this.walkAST(param, callback));
    }

    if (node.hash) {
      Object.values(node.hash.pairs || {}).forEach((pair: any) => {
        this.walkAST(pair.value, callback);
      });
    }
  }
}

// ============================================================================
// Types and Interfaces
// ============================================================================

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

// ============================================================================
// Custom Errors
// ============================================================================

export class TemplateRenderError extends Error {
  constructor(
    message: string,
    public details?: any
  ) {
    super(message);
    this.name = 'TemplateRenderError';
  }
}
"}

{"file_path": "src/ai/dynamic-flow/condition-evaluator.ts", "initial_content": "/**
 * Condition Evaluator for Dynamic Flows
 * Week 1 - Day 4: Condition Evaluator
 * 
 * Safely evaluates conditional expressions for branching logic in flows.
 * Uses a secure expression parser instead of eval() to prevent code injection.
 */

import type { ExecutionContext } from './context-manager';

// ============================================================================
// Condition Evaluator Class
// ============================================================================

export class ConditionEvaluator {
  /**
   * Evaluate a conditional expression against execution context
   * 
   * @param expression - The condition to evaluate (e.g., "input.userType === 'premium'")
   * @param context - The execution context
   * @returns boolean result of the evaluation
   */
  evaluate(expression: string, context: ExecutionContext): boolean {
    try {
      // Sanitize the expression
      const sanitized = this.sanitizeExpression(expression);

      // Build safe variable scope
      const scope = this.buildScope(context);

      // Parse and evaluate the expression safely
      return this.safeEvaluate(sanitized, scope);
    } catch (error) {
      console.error('Condition evaluation failed:', error);
      throw new ConditionEvaluationError(
        `Failed to evaluate condition: ${expression}`,
        { expression, error }
      );
    }
  }

  /**
   * Validate that an expression is safe and well-formed
   */
  validate(expression: string): ValidationResult {
    const errors: string[] = [];

    // Check for empty expression
    if (!expression || expression.trim() === '') {
      errors.push('Expression cannot be empty');
      return { valid: false, errors };
    }

    // Check for dangerous patterns
    const dangerousPatterns = [
      /eval\(/i,
      /Function\(/i,
      /require\(/i,
      /import\s+/i,
      /__proto__/i,
      /constructor/i,
      /process\./i,
      /global\./i,
      /\bwindow\b/i,
      /\bdocument\b/i,
    ];

    for (const pattern of dangerousPatterns) {
      if (pattern.test(expression)) {
        errors.push(`Expression contains potentially dangerous pattern: ${pattern}`);
      }
    }

    // Check for valid syntax (basic check)
    try {
      this.parseExpression(expression);
    } catch (error) {
      errors.push(`Invalid syntax: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }

  /**
   * Sanitize expression to prevent injection
   */
  private sanitizeExpression(expression: string): string {
    // Remove comments
    let sanitized = expression
      .replace(/\/\*[\s\S]*?\*\//g, '')  // Block comments
      .replace(/\/\/.*/g, '');            // Line comments

    // Trim whitespace
    sanitized = sanitized.trim();

    return sanitized;
  }

  /**
   * Build safe scope object from context
   */
  private buildScope(context: ExecutionContext): Record<string, any> {
    const scope: Record<string, any> = {
      // Input variables
      input: context.input,

      // Context variables
      ...Object.fromEntries(context.variables),

      // Step results
      steps: Object.fromEntries(
        Array.from(context.stepResults.entries()).map(([id, result]) => [
          id,
          result.output
        ])
      ),

      // Metadata
      meta: {
        stepCount: context.stepResults.size,
        duration: Date.now() - context.startTime,
        traceId: context.traceId
      }
    };

    return scope;
  }

  /**
   * Safely evaluate expression without using eval()
   * Uses Function constructor with restricted scope
   */
  private safeEvaluate(expression: string, scope: Record<string, any>): boolean {
    // Parse the expression into tokens
    const parsed = this.parseExpression(expression);

    // Evaluate the parsed expression
    return this.evaluateParsedExpression(parsed, scope);
  }

  /**
   * Parse expression into evaluable structure
   */
  private parseExpression(expression: string): ParsedExpression {
    // Simple expression parser for common cases
    // Supports: comparisons, logical operators, property access

    expression = expression.trim();

    // Handle logical operators (AND, OR)
    if (expression.includes('&&') || expression.includes('||')) {
      return this.parseLogicalExpression(expression);
    }

    // Handle comparison operators
    const comparisonMatch = expression.match(/^(.+?)\s*(===|!==|==|!=|<=|>=|<|>)\s*(.+)$/);
    if (comparisonMatch) {
      return {
        type: 'comparison',
        left: comparisonMatch[1].trim(),
        operator: comparisonMatch[2] as ComparisonOperator,
        right: comparisonMatch[3].trim()
      };
    }

    // Handle negation
    if (expression.startsWith('!')) {
      return {
        type: 'negation',
        expression: this.parseExpression(expression.substring(1).trim())
      };
    }

    // Simple variable or value
    return {
      type: 'value',
      value: expression
    };
  }

  /**
   * Parse logical expression (AND/OR)
   */
  private parseLogicalExpression(expression: string): ParsedExpression {
    // Split by || first (lower precedence)
    const orParts = this.splitByOperator(expression, '||');
    if (orParts.length > 1) {
      return {
        type: 'logical',
        operator: '||',
        operands: orParts.map(part => this.parseExpression(part))
      };
    }

    // Split by && (higher precedence)
    const andParts = this.splitByOperator(expression, '&&');
    if (andParts.length > 1) {
      return {
        type: 'logical',
        operator: '&&',
        operands: andParts.map(part => this.parseExpression(part))
      };
    }

    return this.parseExpression(expression);
  }

  /**
   * Split expression by operator, respecting parentheses
   */
  private splitByOperator(expression: string, operator: string): string[] {
    const parts: string[] = [];
    let current = '';
    let depth = 0;
    let i = 0;

    while (i < expression.length) {
      const char = expression[i];

      if (char === '(') {
        depth++;
        current += char;
      } else if (char === ')') {
        depth--;
        current += char;
      } else if (depth === 0 && expression.substring(i, i + operator.length) === operator) {
        parts.push(current.trim());
        current = '';
        i += operator.length - 1;
      } else {
        current += char;
      }

      i++;
    }

    if (current.trim()) {
      parts.push(current.trim());
    }

    return parts.length > 1 ? parts : [expression];
  }

  /**
   * Evaluate parsed expression
   */
  private evaluateParsedExpression(parsed: ParsedExpression, scope: Record<string, any>): boolean {
    switch (parsed.type) {
      case 'comparison':
        const left = this.resolveValue(parsed.left!, scope);
        const right = this.resolveValue(parsed.right!, scope);
        return this.compareValues(left, right, parsed.operator!);

      case 'logical':
        if (parsed.operator === '&&') {
          return parsed.operands!.every(op => this.evaluateParsedExpression(op, scope));
        } else if (parsed.operator === '||') {
          return parsed.operands!.some(op => this.evaluateParsedExpression(op, scope));
        }
        return false;

      case 'negation':
        return !this.evaluateParsedExpression(parsed.expression!, scope);

      case 'value':
        const value = this.resolveValue(parsed.value!, scope);
        return Boolean(value);

      default:
        return false;
    }
  }

  /**
   * Resolve a value from scope or parse as literal
   */
  private resolveValue(value: string, scope: Record<string, any>): any {
    value = value.trim();

    // Handle parentheses
    if (value.startsWith('(') && value.endsWith(')')) {
      value = value.substring(1, value.length - 1).trim();
    }

    // Boolean literals
    if (value === 'true') return true;
    if (value === 'false') return false;

    // Null/undefined
    if (value === 'null') return null;
    if (value === 'undefined') return undefined;

    // Number literals
    if (/^-?\d+(\.\d+)?$/.test(value)) {
      return parseFloat(value);
    }

    // String literals (single or double quotes)
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      return value.substring(1, value.length - 1);
    }

    // Property access (e.g., input.userType or steps.step1.result)
    const parts = value.split('.');
    let current: any = scope;

    for (const part of parts) {
      if (current === null || current === undefined) {
        return undefined;
      }
      current = current[part];
    }

    return current;
  }

  /**
   * Compare two values using operator
   */
  private compareValues(left: any, right: any, operator: ComparisonOperator): boolean {
    switch (operator) {
      case '===': return left === right;
      case '!==': return left !== right;
      case '==': return left == right;
      case '!=': return left != right;
      case '<': return left < right;
      case '>': return left > right;
      case '<=': return left <= right;
      case '>=': return left >= right;
      default: return false;
    }
  }
}

// ============================================================================
// Types and Interfaces
// ============================================================================

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

type ComparisonOperator = '===' | '!==' | '==' | '!=' | '<' | '>' | '<=' | '>=';
type LogicalOperator = '&&' | '||';

type ParsedExpression = 
  | {
      type: 'comparison';
      left: string;
      operator: ComparisonOperator;
      right: string;
    }
  | {
      type: 'logical';
      operator: LogicalOperator;
      operands: ParsedExpression[];
    }
  | {
      type: 'negation';
      expression: ParsedExpression;
    }
  | {
      type: 'value';
      value: string;
    };

// ============================================================================
// Custom Errors
// ============================================================================

export class ConditionEvaluationError extends Error {
  constructor(
    message: string,
    public details?: any
  ) {
    super(message);
    this.name = 'ConditionEvaluationError';
  }
}
"}

{"file_path": "src/ai/dynamic-flow/step-executor.ts", "initial_content": "/**
 * Step Executor for Dynamic Flows
 * Week 1 - Day 4-5: Step Executor
 * 
 * Coordinates execution of individual flow steps.
 * Handles different step types: prompt, tool, condition, loop, parallel
 */

import { ai } from '../genkit';
import type { ExecutionContext, ContextManager } from './context-manager';
import type { TemplateEngine } from './template-engine';
import type { 
  FlowStep, 
  StepResult, 
  PromptStepConfig,
  ToolStepConfig,
  ConditionStepConfig,
  LoopStepConfig,
  ParallelStepConfig 
} from '../../lib/models/flow-config';

// ============================================================================
// Step Executor Class
// ============================================================================

export class StepExecutor {
  constructor(
    private contextManager: ContextManager,
    private templateEngine: TemplateEngine
  ) {}

  /**
   * Execute a single flow step
   */
  async execute(
    step: FlowStep,
    context: ExecutionContext
  ): Promise<StepResult> {
    const startTime = Date.now();

    try {
      // Prepare step input from context
      const input = this.prepareInput(step, context);

      // Execute based on step type
      let result: StepResult;
      switch (step.type) {
        case 'prompt':
          result = await this.executePromptStep(step, input, context);
          break;
        case 'tool':
          result = await this.executeToolStep(step, input, context);
          break;
        case 'condition':
          result = await this.executeConditionStep(step, input, context);
          break;
        case 'loop':
          result = await this.executeLoopStep(step, input, context);
          break;
        case 'parallel':
          result = await this.executeParallelStep(step, input, context);
          break;
        default:
          throw new Error(`Unknown step type: ${(step as any).type}`);
      }

      // Add execution metrics
      result.metrics = {
        ...result.metrics,
        duration: Date.now() - startTime
      };

      return result;

    } catch (error) {
      return {
        status: 'error',
        error: error instanceof Error ? error : new Error(String(error)),
        output: null,
        metrics: {
          duration: Date.now() - startTime
        }
      };
    }
  }

  /**
   * Execute a prompt step (AI generation)
   */
  private async executePromptStep(
    step: FlowStep,
    input: any,
    context: ExecutionContext
  ): Promise<StepResult> {
    const config = step.config as PromptStepConfig;

    // Render prompt with context variables
    const renderedPrompt = this.templateEngine.render(
      config.prompt || '',
      context
    );

    // Execute AI generation
    const result = await ai.generate({
      model: config.model || 'gemini-2.0-flash-exp',
      prompt: renderedPrompt,
      config: {
        temperature: config.temperature ?? 0.7,
        maxOutputTokens: config.maxTokens ?? 2048,
        topK: config.topK,
        topP: config.topP
      }
    });

    return {
      status: 'success',
      output: result.text,
      metrics: {
        tokens: result.usage?.totalTokens || 0,
        inputTokens: result.usage?.inputTokens || 0,
        outputTokens: result.usage?.outputTokens || 0,
        cost: this.calculateCost(result.usage),
        model: config.model
      }
    };
  }

  /**
   * Execute a tool step
   */
  private async executeToolStep(
    step: FlowStep,
    input: any,
    context: ExecutionContext
  ): Promise<StepResult> {
    const config = step.config as ToolStepConfig;

    // Resolve parameters from context
    const parameters = this.resolveParameters(config.parameters || {}, context);

    // Get tool function (simplified - in production, use tool registry)
    const toolFunction = await this.getToolFunction(config.toolName);

    if (!toolFunction) {
      throw new Error(`Tool not found: ${config.toolName}`);
    }

    // Execute tool
    const result = await toolFunction(parameters);

    return {
      status: 'success',
      output: result,
      metrics: {
        tool: config.toolName
      }
    };
  }

  /**
   * Execute a condition step
   */
  private async executeConditionStep(
    step: FlowStep,
    input: any,
    context: ExecutionContext
  ): Promise<StepResult> {
    const config = step.config as ConditionStepConfig;

    // Import ConditionEvaluator dynamically to avoid circular deps
    const { ConditionEvaluator } = await import('./condition-evaluator');
    const evaluator = new ConditionEvaluator();

    // Evaluate condition
    const conditionResult = evaluator.evaluate(
      config.expression,
      context
    );

    return {
      status: 'success',
      output: {
        conditionMet: conditionResult,
        nextStep: conditionResult ? config.onTrue : config.onFalse
      },
      metrics: {}
    };
  }

  /**
   * Execute a loop step
   */
  private async executeLoopStep(
    step: FlowStep,
    input: any,
    context: ExecutionContext
  ): Promise<StepResult> {
    const config = step.config as LoopStepConfig;

    // Get array to iterate over
    const items = this.contextManager.getVariable(context, config.iterateOver);

    if (!Array.isArray(items)) {
      throw new Error(`Loop variable ${config.iterateOver} is not an array`);
    }

    const maxIterations = config.maxIterations || items.length;
    const results: any[] = [];

    // Execute loop steps for each item
    for (let i = 0; i < Math.min(items.length, maxIterations); i++) {
      const item = items[i];

      // Store loop context
      this.contextManager.setVariable(context, 'loop.index', i);
      this.contextManager.setVariable(context, 'loop.item', item);

      // Execute loop body steps
      if (config.steps) {
        const stepResults: any[] = [];
        for (const loopStep of config.steps) {
          const result = await this.execute(loopStep, context);
          stepResults.push(result.output);
        }
        results.push(stepResults);
      }
    }

    return {
      status: 'success',
      output: results,
      metrics: {
        iterations: results.length
      }
    };
  }

  /**
   * Execute parallel steps
   */
  private async executeParallelStep(
    step: FlowStep,
    input: any,
    context: ExecutionContext
  ): Promise<StepResult> {
    const config = step.config as ParallelStepConfig;

    if (!config.steps || config.steps.length === 0) {
      return {
        status: 'success',
        output: [],
        metrics: { parallelSteps: 0 }
      };
    }

    // Execute all parallel steps concurrently
    const promises = config.steps.map(parallelStep =>
      this.execute(parallelStep, context)
    );

    const results = await Promise.allSettled(promises);

    // Check if any failed
    const failures = results.filter(r => r.status === 'rejected');
    if (failures.length > 0 && !config.allowPartialFailure) {
      throw new Error(
        `${failures.length} parallel steps failed`
      );
    }

    return {
      status: 'success',
      output: results.map((r, i) => ({
        stepId: config.steps![i].id,
        status: r.status,
        output: r.status === 'fulfilled' ? r.value.output : null,
        error: r.status === 'rejected' ? r.reason : null
      })),
      metrics: {
        parallelSteps: config.steps.length,
        successful: results.filter(r => r.status === 'fulfilled').length,
        failed: failures.length
      }
    };
  }

  /**
   * Prepare step input from context
   */
  private prepareInput(step: FlowStep, context: ExecutionContext): any {
    if (!step.contextMapping?.input) {
      return context.input;
    }

    const input: any = {};
    for (const [inputKey, contextPath] of Object.entries(step.contextMapping.input)) {
      input[inputKey] = this.contextManager.getVariable(context, contextPath);
    }
    return input;
  }

  /**
   * Resolve parameters from context (handles template variables)
   */
  private resolveParameters(
    parameters: Record<string, any>,
    context: ExecutionContext
  ): Record<string, any> {
    const resolved: Record<string, any> = {};

    for (const [key, value] of Object.entries(parameters)) {
      if (typeof value === 'string' && value.startsWith('{{') && value.endsWith('}}')) {
        // Template variable reference
        const varName = value.slice(2, -2).trim();
        resolved[key] = this.contextManager.getVariable(context, varName);
      } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        // Recursively resolve nested objects
        resolved[key] = this.resolveParameters(value, context);
      } else if (Array.isArray(value)) {
        // Handle arrays
        resolved[key] = value.map(item => 
          typeof item === 'object' && item !== null
            ? this.resolveParameters(item, context)
            : item
        );
      } else {
        resolved[key] = value;
      }
    }

    return resolved;
  }

  /**
   * Get tool function by name
   * In production, this would use a ToolRegistry
   */
  private async getToolFunction(toolName: string): Promise<Function | null> {
    // Import tool registry dynamically
    try {
      const { toolRegistry } = await import('../tool-registry');
      return toolRegistry.getTool(toolName);
    } catch (error) {
      console.warn(`Tool registry not available: ${error}`);
      return null;
    }
  }

  /**
   * Calculate cost based on token usage
   */
  private calculateCost(usage: any): number {
    if (!usage) return 0;

    // Gemini 2.0 Flash pricing (example rates)
    const inputCostPer1M = 0.075;   // $0.075 per 1M input tokens
    const outputCostPer1M = 0.30;   // $0.30 per 1M output tokens

    const inputCost = (usage.inputTokens / 1_000_000) * inputCostPer1M;
    const outputCost = (usage.outputTokens / 1_000_000) * outputCostPer1M;

    return inputCost + outputCost;
  }
}

// ============================================================================
// Exports
// ============================================================================

export type { StepResult } from '../../lib/models/flow-config';
"}

