    version: '1.0.0',
    tags: ['example', 'content-generation'],
    status: 'active' as any,

    // Define input schema
    inputSchema: z.object({
      topic: z.string(),
      tone: z.string().optional()
    }),

    // Define output schema
    outputSchema: z.object({
      content: z.string()
    }),

    // Define flow steps
    steps: [
      {
        id: 'step_1',
        name: 'Generate Content',
        type: 'prompt',
        config: {
          prompt: `You are a professional content writer.

Topic: {{input.topic}}
Tone: {{input.tone}}

Write a comprehensive article about this topic.`,
          model: 'gemini-2.0-flash-exp',
          temperature: 0.7,
          maxTokens: 1000
        },
        contextMapping: {
          output: {
            '': 'content'
          }
        }
      }
    ],

    // Map context variables to output
    outputMapping: {
      content: 'content'
    },

    config: {},
    createdAt: new Date(),
    updatedAt: new Date()
  };

  // Create executor
  const executor = createEnhancedExecutor();

  // Execute flow
  const result = await executor.execute(flowConfig, {
    topic: 'Artificial Intelligence',
    tone: 'professional'
  });

  console.log('✅ Flow executed successfully!');
  console.log('📊 Metrics:', result.metrics);
  console.log('⏱️  Duration:', result.duration, 'ms');
  console.log('📄 Output:', result.output?.content?.substring(0, 200) + '...\n');
}

// ============================================================================
// Example 2: Multi-Step Flow with Context Passing
// ============================================================================

export async function exampleMultiStepFlow() {
  console.log('🚀 Example 2: Multi-Step Flow with Context Passing\n');

  const flowConfig: FlowConfiguration = {
    id: 'example_multistep',
    name: 'research-and-write',
    description: 'Research a topic and write about it',
    version: '1.0.0',
    tags: ['example', 'multi-step'],
    status: 'active' as any,

    inputSchema: z.object({
      query: z.string()
    }),

    outputSchema: z.object({
      research: z.string(),
      article: z.string()
    }),

    steps: [
      {
        id: 'step_1',
        name: 'Research Topic',
        type: 'prompt',
        config: {
          prompt: `Research the following query and provide key findings:

Query: {{input.query}}

Provide 3-5 key points with brief explanations.`,
          model: 'gemini-2.0-flash-exp',
          temperature: 0.3
        },
        contextMapping: {
          output: {
            '': 'researchFindings'
          }
        }
      },
      {
        id: 'step_2',
        name: 'Write Article',
        type: 'prompt',
        config: {
          prompt: `Based on the following research, write a comprehensive article:

Research Findings:
{{researchFindings}}

Create an engaging article that covers all the key points.`,
          model: 'gemini-2.0-flash-exp',
          temperature: 0.7
        },
        contextMapping: {
          output: {
            '': 'finalArticle'
          }
        }
      }
    ],

    outputMapping: {
      research: 'researchFindings',
      article: 'finalArticle'
    },

    config: {},
    createdAt: new Date(),
    updatedAt: new Date()
  };

  const executor = createEnhancedExecutor();
  const result = await executor.execute(flowConfig, {
    query: 'What are the benefits of AI in healthcare?'
  });

  console.log('✅ Multi-step flow executed!');
  console.log('📊 Metrics:', result.metrics);
  console.log('🔍 Research:', result.output?.research?.substring(0, 150) + '...');
  console.log('📝 Article:', result.output?.article?.substring(0, 150) + '...\n');
}

// ============================================================================
// Example 3: Conditional Flow with Branching
// ============================================================================

export async function exampleConditionalFlow() {
  console.log('🚀 Example 3: Conditional Flow with Branching\n');

  const flowConfig: FlowConfiguration = {
    id: 'example_conditional',
    name: 'user-specific-response',
    description: 'Generate response based on user type',
    version: '1.0.0',
    tags: ['example', 'conditional'],
    status: 'active' as any,

    inputSchema: z.object({
      userType: z.enum(['free', 'premium', 'enterprise']),
      question: z.string()
    }),

    outputSchema: z.object({
      response: z.string()
    }),

    steps: [
      {
        id: 'step_free',
        name: 'Free User Response',
        type: 'prompt',
        config: {
          prompt: `Provide a basic response to: {{input.question}}

Keep it concise (max 100 words).`,
          model: 'gemini-2.0-flash-exp'
        },
        condition: {
          expression: 'input.userType === "free"'
        },
        contextMapping: {
          output: { '': 'response' }
        }
      },
      {
        id: 'step_premium',
        name: 'Premium User Response',
        type: 'prompt',
        config: {
          prompt: `Provide a detailed response to: {{input.question}}

Include examples and best practices (max 300 words).`,
          model: 'gemini-2.0-flash-exp'
        },
        condition: {
          expression: 'input.userType === "premium"'
        },
        contextMapping: {
          output: { '': 'response' }
        }
      },
      {
        id: 'step_enterprise',
        name: 'Enterprise User Response',
        type: 'prompt',
        config: {
          prompt: `Provide a comprehensive response to: {{input.question}}

Include detailed analysis, examples, code samples, and references.`,
          model: 'gemini-2.0-flash-exp'
        },
        condition: {
          expression: 'input.userType === "enterprise"'
        },
        contextMapping: {
          output: { '': 'response' }
        }
      }
    ],

    outputMapping: {
      response: 'response'
    },

    config: {},
    createdAt: new Date(),
    updatedAt: new Date()
  };

  const executor = createEnhancedExecutor();

  // Test with different user types
  for (const userType of ['free', 'premium', 'enterprise'] as const) {
    const result = await executor.execute(flowConfig, {
      userType,
      question: 'How do I implement authentication?'
    });

    console.log(`✅ ${userType} user response generated`);
    console.log(`📊 Executed steps: ${result.metrics.successfulSteps}`);
    console.log(`⏭️  Skipped steps: ${result.metrics.skippedSteps}\n`);
  }
}

// ============================================================================
// Example 4: Error Handling with Retry
// ============================================================================

export async function exampleErrorHandling() {
  console.log('🚀 Example 4: Error Handling with Retry\n');

  const flowConfig: FlowConfiguration = {
    id: 'example_retry',
    name: 'resilient-generation',
    description: 'Generate with retry logic',
    version: '1.0.0',
    tags: ['example', 'error-handling'],
    status: 'active' as any,

    inputSchema: z.object({
      prompt: z.string()
    }),

    outputSchema: z.object({
      result: z.string()
    }),

    steps: [
      {
        id: 'step_1',
        name: 'Generate with Retry',
        type: 'prompt',
        config: {
          prompt: '{{input.prompt}}',
          model: 'gemini-2.0-flash-exp'
        },
        errorHandling: {
          retries: 3,
          continueOnError: false
        },
        contextMapping: {
          output: { '': 'result' }
        }
      }
    ],

    outputMapping: {
      result: 'result'
    },

    config: {},
    createdAt: new Date(),
    updatedAt: new Date()
  };

  const executor = createEnhancedExecutor();
  const result = await executor.execute(flowConfig, {
    prompt: 'Explain quantum computing in simple terms'
  });

  console.log('✅ Flow with retry executed');
  console.log('📊 Metrics:', result.metrics);
}

// ============================================================================
// Run Examples
// ============================================================================

export async function runAllExamples() {
  console.log('═══════════════════════════════════════════════════════');
  console.log('    Dynamic Flow System - Usage Examples');
  console.log('═══════════════════════════════════════════════════════\n');

  try {
    await exampleSimpleFlow();
    await exampleMultiStepFlow();
    await exampleConditionalFlow();
    await exampleErrorHandling();

    console.log('═══════════════════════════════════════════════════════');
    console.log('✨ All examples completed successfully!');
    console.log('═══════════════════════════════════════════════════════\n');
  } catch (error) {
    console.error('❌ Error running examples:', error);
  }
}

// Run if executed directly
if (require.main === module) {
  runAllExamples();
}
"}

{"file_path": "QUICK_START_DYNAMIC_FLOWS.md", "initial_content": "# Quick Start - Dynamic Flow System

**Get started with the Dynamic Flow System in 5 minutes!**

---

## 🚀 Quick Start

### 1. Import the Executor

```typescript
import { createEnhancedExecutor } from '@/ai/dynamic-flow';
import { z } from 'zod';
```

### 2. Define Your Flow

```typescript
const flowConfig = {
  id: 'my_flow',
  name: 'my-first-flow',
  description: 'My first dynamic flow',
  version: '1.0.0',
  tags: ['example'],
  status: 'active',

  // What goes in
  inputSchema: z.object({
    topic: z.string()
  }),

  // What comes out
  outputSchema: z.object({
    content: z.string()
  }),

  // What happens
  steps: [
    {
      id: 'step_1',
      name: 'Generate Content',
      type: 'prompt',
      config: {
        prompt: 'Write about {{input.topic}}',
        model: 'gemini-2.0-flash-exp'
      }
    }
  ],

  // How to extract output
  outputMapping: {
    content: 'step_1'
  }
};
```

### 3. Execute

```typescript
const executor = createEnhancedExecutor();
const result = await executor.execute(flowConfig, { 
  topic: 'AI' 
});

console.log(result.output.content);
console.log(result.metrics); // tokens, cost, duration
```

---

## 📚 Common Patterns

### Multi-Step Flow

```typescript
steps: [
  {
    id: 'research',
    type: 'prompt',
    config: { prompt: 'Research {{input.query}}' },
    contextMapping: { output: { '': 'findings' } }
  },
  {
    id: 'write',
    type: 'prompt',
    config: { prompt: 'Write based on {{findings}}' }
  }
]
```

### Conditional Logic

```typescript
{
  id: 'premium_step',
  type: 'prompt',
  condition: {
    expression: 'input.userType === "premium"'
  },
  config: { /* ... */ }
}
```

### Error Handling

```typescript
{
  id: 'resilient_step',
  type: 'prompt',
  errorHandling: {
    retries: 3,
    fallback: 'backup_step',
    continueOnError: false
  },
  config: { /* ... */ }
}
```

### Loop Through Items

```typescript
{
  id: 'process_items',
  type: 'loop',
  config: {
    iterateOver: 'items',
    maxIterations: 10,
    steps: [ /* nested steps */ ]
  }
}
```

### Parallel Execution

```typescript
{
  id: 'parallel_tasks',
  type: 'parallel',
  config: {
    allowPartialFailure: true,
    steps: [
      { id: 'task_1', /* ... */ },
      { id: 'task_2', /* ... */ }
    ]
  }
}
```

---

## 🎯 Step Types

| Type | Purpose | Example |
|------|---------|---------|
| `prompt` | AI generation | Generate content |
| `tool` | Call external tool | Search, RAG retrieval |
| `condition` | Branching logic | Check user type |
| `loop` | Iterate over array | Process multiple items |
| `parallel` | Concurrent execution | Run tasks in parallel |

---

## 🔧 Context Mapping

### Input Mapping
```typescript
contextMapping: {
  input: {
    'stepInputField': 'contextVariable'
  }
}
```

### Output Mapping
```typescript
contextMapping: {
  output: {
    'stepOutputPath': 'contextVariable'
  }
}
```

### Access Variables
- `input.field` - Input data
- `variableName` - Context variable
- `stepId.output` - Step result
- `context.duration` - Special variables

---

## 📊 Result Object

```typescript
{
  success: boolean,
  output: any,              // Your result
  error?: Error,
  traceId: string,
  metrics: {
    totalSteps: number,
    successfulSteps: number,
    failedSteps: number,
    skippedSteps: number,
    totalTokens: number,
    totalCost: number
  },
  duration: number
}
```

---

## 🛠️ Template Variables

In prompts and configs:
- `{{input.field}}` - Access input
- `{{variable}}` - Access context variable
- `{{stepId.output}}` - Access step result

With helpers:
- `{{uppercase text}}` - Transform text
- `{{join items ", "}}` - Join array
- `{{#if condition}}...{{/if}}` - Conditional
- `{{#each items}}...{{/each}}` - Loop

---

## ⚡ Best Practices

### ✅ Do
- Use clear step names
- Define explicit schemas
- Handle errors gracefully
- Map outputs to context
- Use descriptive variable names

### ❌ Don't
- Skip input validation
- Ignore error handling
- Create circular dependencies
- Use eval-like patterns
- Hardcode sensitive data

---

## 🧪 Testing Your Flow

```typescript
import { createEnhancedExecutor } from '@/ai/dynamic-flow';

describe('My Flow', () => {
  it('should generate content', async () => {
    const executor = createEnhancedExecutor();
    const result = await executor.execute(flowConfig, {
      topic: 'Test'
    });

    expect(result.success).toBe(true);
    expect(result.output.content).toBeDefined();
  });
});
```

---

## 📖 More Resources

- **Full Documentation**: `DYNAMIC_FLOWS_EXPANDED_PLAN.md`
- **Implementation Guide**: `IMPLEMENTATION_COMPLETE.md`
- **Usage Examples**: `src/ai/dynamic-flow/example.ts`
- **API Reference**: `src/ai/dynamic-flow/README.md`

---

## 🆘 Troubleshooting

### Flow doesn't execute
- Check flow status is 'active'
- Validate input against schema
- Ensure all step IDs are unique

### Template not rendering
- Check variable names match context
- Use correct syntax: `{{variable}}`
- Verify template helpers syntax

### Condition not working
- Use simple expressions first
- Check variable access paths
- Test condition separately

### Performance issues
- Reduce step count
- Optimize prompts
- Use parallel steps
- Enable caching

---

## 💡 Quick Tips

1. **Start Simple**: Begin with a single prompt step
2. **Test Incrementally**: Add complexity gradually
3. **Use Context Mapping**: Keep data flow clean
4. **Handle Errors**: Always add retry/fallback
5. **Monitor Metrics**: Track tokens and cost

---

**Ready to build dynamic flows?** 🚀

Start with the examples in `src/ai/dynamic-flow/example.ts`!
"}

{"file_path": "src/services/flow-config-service.ts", "initial_content": "/**
 * Flow Configuration Service
 * Week 2 - Day 1: Flow Config Service
 * 
 * Manages flow configurations in Firestore with:
 * - CRUD operations
 * - Versioning
 * - Validation
 * - Caching
 */

import { getFirestore, Timestamp } from 'firebase-admin/firestore';
import type { FlowConfiguration } from '../lib/models/flow-config';
import { z } from 'zod';

// ============================================================================
// Flow Config Service
// ============================================================================

export class FlowConfigService {
  private db = getFirestore();
  private collectionName = 'flow_configs';
  private cache: Map<string, { data: FlowConfiguration; timestamp: number }> = new Map();
  private cacheTTL = 5 * 60 * 1000; // 5 minutes

  // ============================================================================
  // CRUD Operations
  // ============================================================================

  /**
   * Create a new flow configuration
   */
  async createFlow(flow: Omit<FlowConfiguration, 'createdAt' | 'updatedAt'>): Promise<FlowConfiguration> {
    try {
      const now = new Date();
      const flowData: FlowConfiguration = {
        ...flow,
        createdAt: now,
        updatedAt: now
      };

      // Validate flow
      this.validateFlow(flowData);

      // Check if flow ID already exists
      const existing = await this.db.collection(this.collectionName).doc(flow.id).get();
      if (existing.exists) {
        throw new Error(`Flow with ID ${flow.id} already exists`);
      }

      // Store in Firestore
      await this.db.collection(this.collectionName).doc(flow.id).set({
        ...flowData,
        createdAt: Timestamp.fromDate(now),
        updatedAt: Timestamp.fromDate(now)
      });

      // Store initial version
      await this.createVersion(flow.id, flowData);

      // Invalidate cache
      this.invalidateCache(flow.id);

      return flowData;
    } catch (error) {
      throw new Error(`Failed to create flow: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get flow by ID
   */
  async getFlow(flowId: string, version?: string): Promise<FlowConfiguration | null> {
    try {
      // Check cache first (for latest version only)
      if (!version) {
        const cached = this.getFromCache(flowId);
        if (cached) return cached;
      }

      let doc;
      if (version) {
        // Get specific version
        doc = await this.db
          .collection(this.collectionName)
          .doc(flowId)
          .collection('versions')
          .doc(version)
          .get();
      } else {
        // Get latest version
        doc = await this.db.collection(this.collectionName).doc(flowId).get();
      }

      if (!doc.exists) {
        return null;
      }

      const data = doc.data() as any;
      const flow: FlowConfiguration = {
        ...data,
        createdAt: data.createdAt?.toDate() || new Date(),
        updatedAt: data.updatedAt?.toDate() || new Date()
      };

      // Cache latest version
      if (!version) {
        this.setCache(flowId, flow);
      }

      return flow;
    } catch (error) {
      throw new Error(`Failed to get flow: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * List all flows with optional filtering
   */
  async listFlows(options: ListFlowsOptions = {}): Promise<ListFlowsResult> {
    try {
      const {
        status,
        category,
        tags,
        search,
        limit = 50,
        offset = 0,
        orderBy = 'updatedAt',
        orderDirection = 'desc'
      } = options;

      let query = this.db.collection(this.collectionName) as any;

      // Apply filters
      if (status) {
        query = query.where('status', '==', status);
      }

      if (category) {
        query = query.where('category', '==', category);
      }

      if (tags && tags.length > 0) {
        query = query.where('tags', 'array-contains-any', tags);
      }

      // Apply ordering
      query = query.orderBy(orderBy, orderDirection);

      // Get total count (before pagination)
      const countSnapshot = await query.get();
      const total = countSnapshot.size;

      // Apply pagination
      query = query.offset(offset).limit(limit);

      const snapshot = await query.get();
      const flows: FlowConfiguration[] = [];

      for (const doc of snapshot.docs) {
        const data = doc.data();
        const flow: FlowConfiguration = {
          ...data,
          createdAt: data.createdAt?.toDate() || new Date(),
          updatedAt: data.updatedAt?.toDate() || new Date()
        };

        // Apply search filter (client-side for now)
        if (search) {
          const searchLower = search.toLowerCase();
          if (
            flow.name.toLowerCase().includes(searchLower) ||
            flow.description?.toLowerCase().includes(searchLower)
          ) {
            flows.push(flow);
          }
        } else {
          flows.push(flow);
        }
      }

      return {
        flows,
        total,
        limit,
        offset,
        hasMore: offset + flows.length < total
      };
    } catch (error) {
      throw new Error(`Failed to list flows: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Update existing flow (creates new version)
   */
  async updateFlow(
    flowId: string,
    updates: Partial<FlowConfiguration>,
    versionMessage?: string
  ): Promise<FlowConfiguration> {
    try {
      // Get current flow
      const currentFlow = await this.getFlow(flowId);
      if (!currentFlow) {
        throw new Error(`Flow ${flowId} not found`);
      }

      // Increment version
      const versionParts = currentFlow.version.split('.');
      const newVersion = `${versionParts[0]}.${parseInt(versionParts[1]) + 1}.0`;

      const now = new Date();
      const updatedFlow: FlowConfiguration = {
        ...currentFlow,
        ...updates,
        version: newVersion,
        updatedAt: now
      };

      // Validate
      this.validateFlow(updatedFlow);

      // Update main document
      await this.db.collection(this.collectionName).doc(flowId).update({
        ...updates,
        version: newVersion,
        updatedAt: Timestamp.fromDate(now)
      });

      // Create new version
      await this.createVersion(flowId, updatedFlow, versionMessage);

      // Invalidate cache
      this.invalidateCache(flowId);

      return updatedFlow;
    } catch (error) {
      throw new Error(`Failed to update flow: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Delete or deprecate flow
   */
  async deleteFlow(flowId: string, permanent: boolean = false): Promise<void> {
    try {
      if (permanent) {
        // Permanently delete
        await this.db.collection(this.collectionName).doc(flowId).delete();

        // Delete all versions
        const versions = await this.db
          .collection(this.collectionName)
          .doc(flowId)
          .collection('versions')
          .get();

        const batch = this.db.batch();
        versions.docs.forEach(doc => batch.delete(doc.ref));
        await batch.commit();
      } else {
        // Mark as deprecated
        await this.db.collection(this.collectionName).doc(flowId).update({
          status: 'deprecated',
          updatedAt: Timestamp.now()
        });
      }

      // Invalidate cache
      this.invalidateCache(flowId);
    } catch (error) {
      throw new Error(`Failed to delete flow: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Clone a flow with new ID
   */
  async cloneFlow(sourceFlowId: string, newFlowId: string, newName?: string): Promise<FlowConfiguration> {
    try {
      const sourceFlow = await this.getFlow(sourceFlowId);
      if (!sourceFlow) {
        throw new Error(`Source flow ${sourceFlowId} not found`);
      }

      const clonedFlow: Omit<FlowConfiguration, 'createdAt' | 'updatedAt'> = {
        ...sourceFlow,
        id: newFlowId,
        name: newName || `${sourceFlow.name}-copy`,
        version: '1.0.0',
        status: 'draft'
      };

      return await this.createFlow(clonedFlow);
    } catch (error) {
      throw new Error(`Failed to clone flow: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  // ============================================================================
  // Version Management
  // ============================================================================

  /**
   * Create a new version
   */
  private async createVersion(
    flowId: string,
    flow: FlowConfiguration,
    message?: string
  ): Promise<void> {
    const versionData = {
      ...flow,
      versionMessage: message || 'Version created',
      createdAt: Timestamp.fromDate(flow.updatedAt)
    };

    await this.db
      .collection(this.collectionName)
      .doc(flowId)
      .collection('versions')
      .doc(flow.version)
      .set(versionData);
  }

  /**
   * List all versions of a flow
   */
  async listVersions(flowId: string): Promise<FlowVersion[]> {
    try {
      const snapshot = await this.db
        .collection(this.collectionName)
        .doc(flowId)
        .collection('versions')
        .orderBy('createdAt', 'desc')
        .get();

      return snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          version: doc.id,
          createdAt: data.createdAt?.toDate() || new Date(),
          message: data.versionMessage || '',
          status: data.status
        };
      });
    } catch (error) {
      throw new Error(`Failed to list versions: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Restore a specific version
   */
  async restoreVersion(flowId: string, version: string): Promise<FlowConfiguration> {
    try {
      const versionFlow = await this.getFlow(flowId, version);
      if (!versionFlow) {
        throw new Error(`Version ${version} not found for flow ${flowId}`);
      }

      return await this.updateFlow(flowId, versionFlow, `Restored from version ${version}`);
    } catch (error) {
      throw new Error(`Failed to restore version: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  // ============================================================================
  // Validation
  // ============================================================================

  /**
   * Validate flow configuration
   */
  private validateFlow(flow: FlowConfiguration): void {
    // Check required fields
    if (!flow.id || !flow.name || !flow.version) {
      throw new Error('Flow must have id, name, and version');
    }

    // Check steps
    if (!flow.steps || flow.steps.length === 0) {
      throw new Error('Flow must have at least one step');
    }

    // Check for duplicate step IDs
    const stepIds = new Set<string>();
    for (const step of flow.steps) {
      if (stepIds.has(step.id)) {
        throw new Error(`Duplicate step ID: ${step.id}`);
      }
      stepIds.add(step.id);
    }

    // Validate step references
    for (const step of flow.steps) {
      if (step.condition?.onTrue && !stepIds.has(step.condition.onTrue)) {
        throw new Error(`Step ${step.id} references unknown onTrue step: ${step.condition.onTrue}`);
      }
      if (step.condition?.onFalse && !stepIds.has(step.condition.onFalse)) {
        throw new Error(`Step ${step.id} references unknown onFalse step: ${step.condition.onFalse}`);
      }
      if (step.errorHandling?.fallback && !stepIds.has(step.errorHandling.fallback)) {
        throw new Error(`Step ${step.id} references unknown fallback step: ${step.errorHandling.fallback}`);
      }
    }
  }

  // ============================================================================
  // Caching
  // ============================================================================

  /**
   * Get flow from cache
   */
  private getFromCache(flowId: string): FlowConfiguration | null {
    const cached = this.cache.get(flowId);
    if (!cached) return null;

    // Check if expired
    if (Date.now() - cached.timestamp > this.cacheTTL) {
      this.cache.delete(flowId);
      return null;
    }

    return cached.data;
  }

  /**
   * Set flow in cache
   */
  private setCache(flowId: string, flow: FlowConfiguration): void {
    this.cache.set(flowId, {
      data: flow,
      timestamp: Date.now()
    });
  }

  /**
   * Invalidate cache for a flow
   */
  private invalidateCache(flowId: string): void {
    this.cache.delete(flowId);
  }

  /**
   * Clear entire cache
   */
  clearCache(): void {
    this.cache.clear();
  }

  // ============================================================================
  // Statistics
  // ============================================================================

  /**
   * Get flow statistics
   */
  async getFlowStats(flowId: string): Promise<FlowStats | null> {
    try {
      const statsDoc = await this.db
        .collection('flow_statistics')
        .doc(flowId)
        .get();

      if (!statsDoc.exists) {
        return null;
      }

      const data = statsDoc.data()!;
      return {
        flowId,
        totalExecutions: data.totalExecutions || 0,
        successfulExecutions: data.successfulExecutions || 0,
        failedExecutions: data.failedExecutions || 0,
        avgDuration: data.avgDuration || 0,
        totalTokens: data.totalTokens || 0,
        totalCost: data.totalCost || 0,
        lastExecuted: data.lastExecuted?.toDate()
      };
    } catch (error) {
      console.error('Failed to get flow stats:', error);
      return null;
    }
  }
}

// ============================================================================
// Types and Interfaces
// ============================================================================

export interface ListFlowsOptions {
  status?: 'active' | 'draft' | 'deprecated';
  category?: string;
  tags?: string[];
  search?: string;
  limit?: number;
  offset?: number;
  orderBy?: string;
  orderDirection?: 'asc' | 'desc';
}

export interface ListFlowsResult {
  flows: FlowConfiguration[];
  total: number;
  limit: number;
  offset: number;
  hasMore: boolean;
}

export interface FlowVersion {
  version: string;
  createdAt: Date;
  message: string;
  status: string;
}

export interface FlowStats {
  flowId: string;
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  avgDuration: number;
  totalTokens: number;
  totalCost: number;
  lastExecuted?: Date;
}

// ============================================================================
// Singleton Instance
// ============================================================================

let flowConfigServiceInstance: FlowConfigService | null = null;

export function getFlowConfigService(): FlowConfigService {
  if (!flowConfigServiceInstance) {
    flowConfigServiceInstance = new FlowConfigService();
  }
  return flowConfigServiceInstance;
}
"}

{"file_path": "src/services/execution-trace-service.ts", "initial_content": "/**
 * Execution Trace Service
 * Week 2 - Day 2: Execution Trace Service
 * 
 * Manages execution traces in Firestore for:
 * - Monitoring flow executions
 * - Debugging and troubleshooting
 * - Analytics and metrics
 * - Performance tracking
 */

import { getFirestore, Timestamp, FieldValue } from 'firebase-admin/firestore';
import type { ExecutionResult, ExecutionMetrics } from '../ai/dynamic-flow/executor';

// ============================================================================
// Execution Trace Service
// ============================================================================

export class ExecutionTraceService {
  private db = getFirestore();
  private collectionName = 'execution_traces';
  private statsCollection = 'flow_statistics';

  // ============================================================================
  // Trace Management
  // ============================================================================

  /**
   * Start a new execution trace
   */
  async startTrace(
    flowId: string,
    flowVersion: string,
    input: any,
    options?: TraceOptions
  ): Promise<ExecutionTrace> {
    try {
      const traceId = this.generateTraceId();
      const now = new Date();

      const trace: ExecutionTrace = {
        id: traceId,
        flowId,
        flowVersion,
        input,
        status: 'running',
        startTime: now,
        userId: options?.userId,
        sessionId: options?.sessionId,
        steps: [],
        context: {},
        metrics: {
          totalTokens: 0,
          totalCost: 0,
          cacheHits: 0,
          cacheMisses: 0
        }
      };

      // Store in Firestore
      await this.db.collection(this.collectionName).doc(traceId).set({
        ...trace,
        startTime: Timestamp.fromDate(now)
      });

      return trace;
    } catch (error) {
      throw new Error(`Failed to start trace: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Complete an execution trace
   */
  async completeTrace(
    traceId: string,
    result: {
      status: 'success' | 'error' | 'timeout';
      output?: any;
      error?: any;
      metrics?: ExecutionMetrics;
    }
  ): Promise<void> {
    try {
      const now = new Date();
      const traceRef = this.db.collection(this.collectionName).doc(traceId);

      // Get current trace to calculate duration
      const traceDoc = await traceRef.get();
      if (!traceDoc.exists) {
        throw new Error(`Trace ${traceId} not found`);
      }

      const traceData = traceDoc.data()!;
      const startTime = traceData.startTime?.toDate() || now;
      const duration = now.getTime() - startTime.getTime();

      // Update trace
      await traceRef.update({
        status: result.status,
        output: result.output,
        error: result.error ? {
          message: result.error.message || String(result.error),
          stack: result.error.stack,
          name: result.error.name
        } : null,
        endTime: Timestamp.fromDate(now),
        duration,
        metrics: result.metrics || traceData.metrics
      });

      // Update flow statistics
      await this.updateFlowStatistics(traceData.flowId, {
        status: result.status,
        duration,
        metrics: result.metrics
      });
    } catch (error) {
      console.error('Failed to complete trace:', error);
      throw new Error(`Failed to complete trace: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Record a successful step execution
   */
  async recordStepSuccess(
    traceId: string,
    stepId: string,
    result: StepTraceResult
  ): Promise<void> {
    try {
      const stepTrace: StepTrace = {
        stepId,
        stepName: result.stepName || stepId,
        startTime: result.startTime || new Date(),
        endTime: result.endTime || new Date(),
        duration: result.duration || 0,
        status: 'success',
        input: result.input,
        output: result.output,
        metrics: result.metrics
      };

      await this.db.collection(this.collectionName).doc(traceId).update({
        steps: FieldValue.arrayUnion(stepTrace)
      });
    } catch (error) {
      console.error('Failed to record step success:', error);
    }
  }

  /**
   * Record a step error
   */
  async recordStepError(
    traceId: string,
    stepId: string,
    error: Error
  ): Promise<void> {
    try {
      const stepTrace: StepTrace = {
        stepId,
        stepName: stepId,
        startTime: new Date(),
        endTime: new Date(),
        duration: 0,
        status: 'error',
        error: {
          message: error.message,
          stack: error.stack,
          name: error.name
        }
      };

      await this.db.collection(this.collectionName).doc(traceId).update({
        steps: FieldValue.arrayUnion(stepTrace)
      });
    } catch (err) {
      console.error('Failed to record step error:', err);
    }
  }

  /**
   * Record a skipped step
   */
  async recordSkippedStep(traceId: string, stepId: string): Promise<void> {
    try {
      const stepTrace: StepTrace = {
        stepId,
        stepName: stepId,
        startTime: new Date(),
        endTime: new Date(),
        duration: 0,
        status: 'skipped'
      };

      await this.db.collection(this.collectionName).doc(traceId).update({
        steps: FieldValue.arrayUnion(stepTrace)
      });
    } catch (error) {
      console.error('Failed to record skipped step:', error);
    }
  }

  /**
   * Record a step attempt (for retries)
   */
  async recordStepAttempt(
    traceId: string,
    stepId: string,
    attempt: number,
    error: any
  ): Promise<void> {
    try {
      await this.db.collection(this.collectionName).doc(traceId).update({
        [`attempts.${stepId}`]: FieldValue.arrayUnion({
          attempt,
          timestamp: Timestamp.now(),
          error: error.message || String(error)
        })
      });
    } catch (err) {
      console.error('Failed to record step attempt:', err);
    }
  }

  // ============================================================================
  // Query Traces
  // ============================================================================

  /**
   * Get trace by ID
   */
  async getTrace(traceId: string): Promise<ExecutionTrace | null> {
    try {
      const doc = await this.db.collection(this.collectionName).doc(traceId).get();

      if (!doc.exists) {
        return null;
      }

      const data = doc.data()!;
      return {
        ...data,
        startTime: data.startTime?.toDate() || new Date(),
        endTime: data.endTime?.toDate()
      } as ExecutionTrace;
    } catch (error) {
      throw new Error(`Failed to get trace: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * List traces with filtering
   */
  async listTraces(options: ListTracesOptions = {}): Promise<ListTracesResult> {
    try {
      const {
        flowId,
        userId,
        status,
        startDate,
        endDate,
        limit = 50,
        offset = 0
      } = options;

      let query = this.db.collection(this.collectionName) as any;

      // Apply filters
      if (flowId) {
        query = query.where('flowId', '==', flowId);
      }

      if (userId) {
        query = query.where('userId', '==', userId);
      }

      if (status) {
        query = query.where('status', '==', status);
      }

      if (startDate) {
        query = query.where('startTime', '>=', Timestamp.fromDate(startDate));
      }

      if (endDate) {
        query = query.where('startTime', '<=', Timestamp.fromDate(endDate));
      }

      // Order by start time (descending)
      query = query.orderBy('startTime', 'desc');

      // Get total count
      const countSnapshot = await query.get();
      const total = countSnapshot.size;

      // Apply pagination
      query = query.offset(offset).limit(limit);
      const snapshot = await query.get();

      const traces: ExecutionTrace[] = snapshot.docs.map((doc: any) => {
        const data = doc.data();
        return {
          ...data,
          startTime: data.startTime?.toDate() || new Date(),
          endTime: data.endTime?.toDate()
        };
      });

      return {
        traces,
        total,
        limit,
        offset,
        hasMore: offset + traces.length < total
      };
    } catch (error) {
      throw new Error(`Failed to list traces: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get recent traces for a flow
   */
  async getRecentTraces(flowId: string, limit: number = 100): Promise<ExecutionTrace[]> {
    try {
      const snapshot = await this.db
        .collection(this.collectionName)
        .where('flowId', '==', flowId)
        .orderBy('startTime', 'desc')
        .limit(limit)
        .get();

      return snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          startTime: data.startTime?.toDate() || new Date(),
          endTime: data.endTime?.toDate()
        } as ExecutionTrace;
      });
    } catch (error) {
      throw new Error(`Failed to get recent traces: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  // ============================================================================
  // Analytics
  // ============================================================================

  /**
   * Get execution analytics for a flow
   */
  async getFlowAnalytics(
    flowId: string,
    options: AnalyticsOptions = {}
  ): Promise<FlowAnalytics> {
    try {
      const { startDate, endDate, limit = 1000 } = options;

      let query = this.db
        .collection(this.collectionName)
        .where('flowId', '==', flowId) as any;

      if (startDate) {
        query = query.where('startTime', '>=', Timestamp.fromDate(startDate));
      }

      if (endDate) {
        query = query.where('startTime', '<=', Timestamp.fromDate(endDate));
      }

      query = query.limit(limit);
      const snapshot = await query.get();

      const traces = snapshot.docs.map((doc: any) => doc.data());

      // Calculate analytics
      const totalExecutions = traces.length;
      const successful = traces.filter((t: any) => t.status === 'success').length;
      const failed = traces.filter((t: any) => t.status === 'error').length;
      const durations = traces.filter((t: any) => t.duration).map((t: any) => t.duration);
      const tokens = traces.filter((t: any) => t.metrics?.totalTokens).map((t: any) => t.metrics.totalTokens);
      const costs = traces.filter((t: any) => t.metrics?.totalCost).map((t: any) => t.metrics.totalCost);

      return {
        flowId,
        totalExecutions,
        successfulExecutions: successful,
        failedExecutions: failed,
        successRate: totalExecutions > 0 ? successful / totalExecutions : 0,
        avgDuration: durations.length > 0 ? durations.reduce((a, b) => a + b, 0) / durations.length : 0,
        minDuration: durations.length > 0 ? Math.min(...durations) : 0,
        maxDuration: durations.length > 0 ? Math.max(...durations) : 0,
        p50Duration: this.percentile(durations, 50),
        p95Duration: this.percentile(durations, 95),
        p99Duration: this.percentile(durations, 99),
        totalTokens: tokens.reduce((a, b) => a + b, 0),
        totalCost: costs.reduce((a, b) => a + b, 0),
        avgTokens: tokens.length > 0 ? tokens.reduce((a, b) => a + b, 0) / tokens.length : 0,
        avgCost: costs.length > 0 ? costs.reduce((a, b) => a + b, 0) / costs.length : 0
      };
    } catch (error) {
      throw new Error(`Failed to get analytics: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  // ============================================================================
  // Statistics Updates
  // ============================================================================

  /**
   * Update flow statistics
   */
  private async updateFlowStatistics(
    flowId: string,
    execution: {
      status: string;
      duration: number;
      metrics?: ExecutionMetrics;
    }
  ): Promise<void> {
    try {
      const statsRef = this.db.collection(this.statsCollection).doc(flowId);

      await this.db.runTransaction(async (transaction) => {
        const doc = await transaction.get(statsRef);

        if (!doc.exists) {
          // Create new stats document
          transaction.set(statsRef, {
            flowId,
            totalExecutions: 1,
            successfulExecutions: execution.status === 'success' ? 1 : 0,
            failedExecutions: execution.status === 'error' ? 1 : 0,
            avgDuration: execution.duration,
            totalTokens: execution.metrics?.totalTokens || 0,
            totalCost: execution.metrics?.totalCost || 0,
            lastExecuted: Timestamp.now()
          });
        } else {
          // Update existing stats
          const data = doc.data()!;
          const totalExec = data.totalExecutions + 1;

          transaction.update(statsRef, {
            totalExecutions: totalExec,
            successfulExecutions: data.successfulExecutions + (execution.status === 'success' ? 1 : 0),
            failedExecutions: data.failedExecutions + (execution.status === 'error' ? 1 : 0),
            avgDuration: (data.avgDuration * data.totalExecutions + execution.duration) / totalExec,
            totalTokens: data.totalTokens + (execution.metrics?.totalTokens || 0),
            totalCost: data.totalCost + (execution.metrics?.totalCost || 0),
            lastExecuted: Timestamp.now()
          });
        }
      });
    } catch (error) {
      console.error('Failed to update flow statistics:', error);
    }
  }

  // ============================================================================
  // Utilities
  // ============================================================================

  /**
   * Generate unique trace ID
   */
  private generateTraceId(): string {
    return `trace_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Calculate percentile
   */
  private percentile(numbers: number[], p: number): number {
    if (numbers.length === 0) return 0;
    const sorted = [...numbers].sort((a, b) => a - b);
    const index = Math.ceil((p / 100) * sorted.length) - 1;
    return sorted[Math.max(0, index)];
  }

  /**
   * Delete old traces (cleanup)
   */
  async deleteOldTraces(daysOld: number = 90): Promise<number> {
    try {
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - daysOld);

      const snapshot = await this.db
        .collection(this.collectionName)
        .where('startTime', '<', Timestamp.fromDate(cutoffDate))
        .limit(500)
        .get();

      const batch = this.db.batch();
      snapshot.docs.forEach(doc => batch.delete(doc.ref));
      await batch.commit();

      return snapshot.size;
    } catch (error) {
      throw new Error(`Failed to delete old traces: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }
}

// ============================================================================
// Types and Interfaces
// ============================================================================

export interface ExecutionTrace {
  id: string;
  flowId: string;
  flowVersion: string;
  input: any;
  output?: any;
  error?: any;
  status: 'running' | 'success' | 'error' | 'timeout';
  startTime: Date;
  endTime?: Date;
  duration?: number;
  userId?: string;
  sessionId?: string;
  steps: StepTrace[];
  context: Record<string, any>;
  metrics: {
    totalTokens: number;
    totalCost: number;
    cacheHits: number;
    cacheMisses: number;
  };
}

export interface StepTrace {
  stepId: string;
  stepName: string;
  startTime: Date;
  endTime: Date;
  duration: number;
  status: 'success' | 'error' | 'skipped';
  input?: any;
  output?: any;
  error?: any;
  metrics?: any;
}

export interface StepTraceResult {
  stepName?: string;
  startTime?: Date;
  endTime?: Date;
  duration?: number;
  input?: any;
  output?: any;
  metrics?: any;
}

export interface TraceOptions {
  userId?: string;
  sessionId?: string;
}

export interface ListTracesOptions {
  flowId?: string;
  userId?: string;
  status?: 'running' | 'success' | 'error' | 'timeout';
  startDate?: Date;
  endDate?: Date;
  limit?: number;
  offset?: number;
}

export interface ListTracesResult {
  traces: ExecutionTrace[];
  total: number;
  limit: number;
  offset: number;
  hasMore: boolean;
}

export interface AnalyticsOptions {
  startDate?: Date;
  endDate?: Date;
  limit?: number;
}

export interface FlowAnalytics {
  flowId: string;
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  successRate: number;
  avgDuration: number;
  minDuration: number;
  maxDuration: number;
  p50Duration: number;
  p95Duration: number;
  p99Duration: number;
  totalTokens: number;
  totalCost: number;
  avgTokens: number;
  avgCost: number;
}

// ============================================================================
// Singleton Instance
// ============================================================================

let executionTraceServiceInstance: ExecutionTraceService | null = null;

export function getExecutionTraceService(): ExecutionTraceService {
  if (!executionTraceServiceInstance) {
    executionTraceServiceInstance = new ExecutionTraceService();
  }
  return executionTraceServiceInstance;
}
"}

