 * Flow Management API Routes
 * Week 2 - Day 4: API Routes
 * 
 * Endpoints:
 * GET    /api/admin/flows       - List flows
 * POST   /api/admin/flows       - Create flow
 */

import { NextRequest, NextResponse } from 'next/server';
import { getFlowConfigService } from '@/services/flow-config-service';
import { z } from 'zod';

// ============================================================================
// GET - List Flows
// ============================================================================

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);

    const options = {
      status: searchParams.get('status') as any,
      category: searchParams.get('category') || undefined,
      search: searchParams.get('search') || undefined,
      limit: parseInt(searchParams.get('limit') || '50'),
      offset: parseInt(searchParams.get('offset') || '0'),
      orderBy: searchParams.get('orderBy') || 'updatedAt',
      orderDirection: (searchParams.get('orderDirection') || 'desc') as 'asc' | 'desc'
    };

    const flowService = getFlowConfigService();
    const result = await flowService.listFlows(options);

    return NextResponse.json(result, { status: 200 });
  } catch (error) {
    console.error('Error listing flows:', error);
    return NextResponse.json(
      { error: 'Failed to list flows', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

// ============================================================================
// POST - Create Flow
// ============================================================================

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    // Validate required fields
    if (!body.id || !body.name || !body.version) {
      return NextResponse.json(
        { error: 'Missing required fields: id, name, version' },
        { status: 400 }
      );
    }

    const flowService = getFlowConfigService();
    const flow = await flowService.createFlow(body);

    return NextResponse.json(
      { message: 'Flow created successfully', flow },
      { status: 201 }
    );
  } catch (error) {
    console.error('Error creating flow:', error);
    return NextResponse.json(
      { error: 'Failed to create flow', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}
"}

