  const nodeTypes: NodeTypes = useMemo(
    () => ({
      stepNode: StepNode,
    }),
    []
  );

  // Handle new connections
  const onConnect = useCallback(
    (params: Connection) => {
      if (readOnly) return;
      setEdges((eds) => addEdge(params, eds));
    },
    [setEdges, readOnly]
  );

  // Handle node click
  const onNodeClick = useCallback(
    (_event: React.MouseEvent, node: Node) => {
      setSelectedNode(node);
      setShowConfigPanel(true);
    },
    []
  );

  // Add new step
  const addStep = useCallback(
    (type: FlowStep['type']) => {
      if (readOnly) return;

      const newNode: Node = {
        id: `step_${Date.now()}`,
        type: 'stepNode',
        position: {
          x: Math.random() * 400 + 100,
          y: Math.random() * 400 + 100,
        },
        data: {
          step: {
            id: `step_${Date.now()}`,
            name: `New ${type} Step`,
            type,
            config: {},
          },
          onEdit: () => {
            setSelectedNode(newNode);
            setShowConfigPanel(true);
          },
          onDelete: () => {
            setNodes((nds) => nds.filter((n) => n.id !== newNode.id));
            setEdges((eds) => eds.filter((e) => e.source !== newNode.id && e.target !== newNode.id));
          },
        },
      };

      setNodes((nds) => [...nds, newNode]);
    },
    [setNodes, setEdges, readOnly]
  );

  // Save flow
  const handleSave = useCallback(() => {
    if (!onSave) return;

    // Convert nodes and edges to flow config
    const steps: FlowStep[] = nodes.map((node) => node.data.step);

    const config: FlowConfiguration = {
      id: flowConfig?.id || `flow_${Date.now()}`,
      name: flowConfig?.name || 'New Flow',
      description: flowConfig?.description || '',
      version: flowConfig?.version || '1.0.0',
      tags: flowConfig?.tags || [],
      status: flowConfig?.status || 'draft',
      inputSchema: flowConfig?.inputSchema || {},
      outputSchema: flowConfig?.outputSchema || {},
      steps,
      config: flowConfig?.config || {},
      createdAt: flowConfig?.createdAt || new Date(),
      updatedAt: new Date(),
    };

    onSave(config);
  }, [nodes, edges, flowConfig, onSave]);

  // Execute flow
  const handleExecute = useCallback(() => {
    if (!onExecute) return;

    const steps: FlowStep[] = nodes.map((node) => node.data.step);
    const config: FlowConfiguration = {
      ...flowConfig!,
      steps,
      updatedAt: new Date(),
    };

    onExecute(config);
  }, [nodes, flowConfig, onExecute]);

  // Export as JSON
  const handleExport = useCallback(() => {
    const steps: FlowStep[] = nodes.map((node) => node.data.step);
    const config = {
      ...flowConfig,
      steps,
    };

    const blob = new Blob([JSON.stringify(config, null, 2)], {
      type: 'application/json',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${flowConfig?.name || 'flow'}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, [nodes, flowConfig]);

  return (
    <div className="h-full w-full flex flex-col">
      {/* Toolbar */}
      <Card className="p-4 mb-4 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h2 className="text-lg font-semibold">
            {flowConfig?.name || 'Flow Builder'}
          </h2>
          <span className="text-sm text-muted-foreground">
            v{flowConfig?.version || '1.0.0'}
          </span>
        </div>

        <div className="flex items-center gap-2">
          {!readOnly && (
            <>
              {/* Add Step Buttons */}
              <Button
                variant="outline"
                size="sm"
                onClick={() => addStep('prompt')}
              >
                <Plus className="w-4 h-4 mr-1" />
                Prompt
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => addStep('tool')}
              >
                <Plus className="w-4 h-4 mr-1" />
                Tool
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => addStep('condition')}
              >
                <Plus className="w-4 h-4 mr-1" />
                Condition
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => addStep('loop')}
              >
                <Plus className="w-4 h-4 mr-1" />
                Loop
              </Button>

              <div className="h-6 w-px bg-border mx-2" />

              {/* Action Buttons */}
              <Button
                variant="default"
                size="sm"
                onClick={handleSave}
              >
                <Save className="w-4 h-4 mr-1" />
                Save
              </Button>
            </>
          )}

          <Button
            variant="secondary"
            size="sm"
            onClick={handleExecute}
            disabled={!flowConfig || nodes.length === 0}
          >
            <Play className="w-4 h-4 mr-1" />
            Execute
          </Button>

          <Button
            variant="ghost"
            size="sm"
            onClick={handleExport}
          >
            <FileJson className="w-4 h-4 mr-1" />
            Export
          </Button>
        </div>
      </Card>

      {/* Canvas */}
      <div className="flex-1 border rounded-lg overflow-hidden bg-background">
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onNodeClick={onNodeClick}
          nodeTypes={nodeTypes}
          fitView
          className="bg-background"
        >
          <Background />
          <Controls />
          <MiniMap
            nodeColor={(node) => {
              switch (node.data.step?.type) {
                case 'prompt':
                  return '#3b82f6';
                case 'tool':
                  return '#10b981';
                case 'condition':
                  return '#f59e0b';
                case 'loop':
                  return '#8b5cf6';
                case 'parallel':
                  return '#ec4899';
                default:
                  return '#6b7280';
              }
            }}
          />
        </ReactFlow>
      </div>

      {/* Configuration Panel */}
      {showConfigPanel && selectedNode && (
        <StepConfigPanel
          step={selectedNode.data.step}
          onUpdate={(updatedStep) => {
            setNodes((nds) =>
              nds.map((n) =>
                n.id === selectedNode.id
                  ? { ...n, data: { ...n.data, step: updatedStep } }
                  : n
              )
            );
          }}
          onClose={() => {
            setShowConfigPanel(false);
            setSelectedNode(null);
          }}
        />
      )}

      {/* Empty State */}
      {nodes.length === 0 && !readOnly && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="text-center">
            <p className="text-muted-foreground mb-4">
              Start building your flow by adding steps
            </p>
            <div className="flex gap-2 pointer-events-auto justify-center">
              <Button
                variant="outline"
                onClick={() => addStep('prompt')}
              >
                Add Prompt Step
              </Button>
              <Button
                variant="outline"
                onClick={() => addStep('tool')}
              >
                Add Tool Step
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
"}

{"file_path": "src/components/admin/flow-builder/StepNode.tsx", "initial_content": "/**
 * Step Node Component
 * Week 3 - Day 1: Visual Step Representation
 * 
 * Individual step node for the flow builder
 */

'use client';

import React from 'react';
import { Handle, Position, type NodeProps } from 'reactflow';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  MessageSquare,
  Wrench,
  GitBranch,
  Repeat,
  Layers,
  Settings,
  Trash2,
} from 'lucide-react';
import type { FlowStep } from '@/lib/models/flow-config';

// ============================================================================
// Step Node Component
// ============================================================================

interface StepNodeData {
  step: FlowStep;
  onEdit?: () => void;
  onDelete?: () => void;
}

export function StepNode({ data }: NodeProps<StepNodeData>) {
  const { step, onEdit, onDelete } = data;

  // Get icon based on step type
  const getStepIcon = () => {
    switch (step.type) {
      case 'prompt':
        return <MessageSquare className="w-4 h-4" />;
      case 'tool':
        return <Wrench className="w-4 h-4" />;
      case 'condition':
        return <GitBranch className="w-4 h-4" />;
      case 'loop':
        return <Repeat className="w-4 h-4" />;
      case 'parallel':
        return <Layers className="w-4 h-4" />;
      default:
        return null;
    }
  };

  // Get color based on step type
  const getStepColor = () => {
    switch (step.type) {
      case 'prompt':
        return 'bg-blue-500';
      case 'tool':
        return 'bg-green-500';
      case 'condition':
        return 'bg-amber-500';
      case 'loop':
        return 'bg-purple-500';
      case 'parallel':
        return 'bg-pink-500';
      default:
        return 'bg-gray-500';
    }
  };

  return (
    <>
      {/* Input Handle */}
      <Handle
        type="target"
        position={Position.Top}
        className="w-3 h-3 !bg-primary"
      />

      <Card className="min-w-[200px] max-w-[300px] shadow-lg">
        {/* Header */}
        <div className={`${getStepColor()} px-3 py-2 rounded-t-lg flex items-center justify-between`}>
          <div className="flex items-center gap-2 text-white">
            {getStepIcon()}
            <span className="font-medium text-sm">
              {step.type.charAt(0).toUpperCase() + step.type.slice(1)}
            </span>
          </div>
          <div className="flex items-center gap-1">
            {onEdit && (
              <Button
                variant="ghost"
                size="sm"
                className="h-6 w-6 p-0 text-white hover:bg-white/20"
                onClick={(e) => {
                  e.stopPropagation();
                  onEdit();
                }}
              >
                <Settings className="w-3 h-3" />
              </Button>
            )}
            {onDelete && (
              <Button
                variant="ghost"
                size="sm"
                className="h-6 w-6 p-0 text-white hover:bg-red-500"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete();
                }}
              >
                <Trash2 className="w-3 h-3" />
              </Button>
            )}
          </div>
        </div>

        {/* Content */}
        <div className="p-3 space-y-2">
          <div>
            <p className="font-medium text-sm">{step.name}</p>
            <p className="text-xs text-muted-foreground">ID: {step.id}</p>
          </div>

          {/* Step-specific info */}
          {step.type === 'prompt' && step.config.prompt && (
            <p className="text-xs text-muted-foreground line-clamp-2">
              {step.config.prompt.substring(0, 60)}...
            </p>
          )}

          {step.type === 'tool' && step.config.toolName && (
            <Badge variant="secondary" className="text-xs">
              {step.config.toolName}
            </Badge>
          )}

          {step.type === 'condition' && step.condition?.expression && (
            <p className="text-xs font-mono bg-muted px-2 py-1 rounded">
              {step.condition.expression}
            </p>
          )}

          {step.type === 'loop' && step.config.iterateOver && (
            <p className="text-xs text-muted-foreground">
              Loop over: {step.config.iterateOver}
            </p>
          )}

          {/* Error handling badge */}
          {step.errorHandling && (
            <Badge variant="outline" className="text-xs">
              {step.errorHandling.retries ? `Retries: ${step.errorHandling.retries}` : 'Error Handling'}
            </Badge>
          )}

          {/* Condition badge */}
          {step.condition && (
            <Badge variant="outline" className="text-xs">
              Conditional
            </Badge>
          )}
        </div>
      </Card>

      {/* Output Handle */}
      <Handle
        type="source"
        position={Position.Bottom}
        className="w-3 h-3 !bg-primary"
      />
    </>
  );
}
"}

{"file_path": "src/components/admin/flow-builder/StepConfigPanel.tsx", "initial_content": "/**
 * Step Configuration Panel
 * Week 3 - Day 1: Step Editor
 * 
 * Side panel for editing step configuration
 */

'use client';

import React, { useState } from 'react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card } from '@/components/ui/card';
import { Save } from 'lucide-react';
import type { FlowStep } from '@/lib/models/flow-config';

// ============================================================================
// Step Config Panel Component
// ============================================================================

interface StepConfigPanelProps {
  step: FlowStep;
  onUpdate: (step: FlowStep) => void;
  onClose: () => void;
}

export function StepConfigPanel({ step, onUpdate, onClose }: StepConfigPanelProps) {
  const [editedStep, setEditedStep] = useState<FlowStep>(step);

  const handleSave = () => {
    onUpdate(editedStep);
    onClose();
  };

  const updateField = (field: string, value: any) => {
    setEditedStep((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const updateConfig = (field: string, value: any) => {
    setEditedStep((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        [field]: value,
      },
    }));
  };

  const updateCondition = (field: string, value: any) => {
    setEditedStep((prev) => ({
      ...prev,
      condition: {
        ...prev.condition,
        [field]: value,
      },
    }));
  };

  const updateErrorHandling = (field: string, value: any) => {
    setEditedStep((prev) => ({
      ...prev,
      errorHandling: {
        ...prev.errorHandling,
        [field]: value,
      },
    }));
  };

  return (
    <Sheet open={true} onOpenChange={onClose}>
      <SheetContent className="sm:max-w-[600px] overflow-y-auto">
        <SheetHeader>
          <SheetTitle>Configure Step</SheetTitle>
          <SheetDescription>
            Edit the configuration for this {editedStep.type} step
          </SheetDescription>
        </SheetHeader>

        <Tabs defaultValue="basic" className="mt-6">
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="basic">Basic</TabsTrigger>
            <TabsTrigger value="config">Config</TabsTrigger>
            <TabsTrigger value="advanced">Advanced</TabsTrigger>
            <TabsTrigger value="mapping">Mapping</TabsTrigger>
          </TabsList>

          {/* Basic Tab */}
          <TabsContent value="basic" className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Step Name</Label>
              <Input
                id="name"
                value={editedStep.name}
                onChange={(e) => updateField('name', e.target.value)}
                placeholder="Enter step name"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="id">Step ID</Label>
              <Input
                id="id"
                value={editedStep.id}
                onChange={(e) => updateField('id', e.target.value)}
                placeholder="step_1"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="type">Step Type</Label>
              <Select
                value={editedStep.type}
                onValueChange={(value) => updateField('type', value)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="prompt">Prompt</SelectItem>
                  <SelectItem value="tool">Tool</SelectItem>
                  <SelectItem value="condition">Condition</SelectItem>
                  <SelectItem value="loop">Loop</SelectItem>
                  <SelectItem value="parallel">Parallel</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </TabsContent>

          {/* Config Tab */}
          <TabsContent value="config" className="space-y-4">
            {editedStep.type === 'prompt' && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="prompt">Prompt Template</Label>
                  <Textarea
                    id="prompt"
                    value={editedStep.config.prompt || ''}
                    onChange={(e) => updateConfig('prompt', e.target.value)}
                    placeholder="Enter your prompt template with {{variables}}"
                    rows={6}
                    className="font-mono text-sm"
                  />
                  <p className="text-xs text-muted-foreground">
                    Use {`{{input.field}}`} to access input variables
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="model">Model</Label>
                    <Select
                      value={editedStep.config.model || 'gemini-2.0-flash-exp'}
                      onValueChange={(value) => updateConfig('model', value)}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="gemini-2.0-flash-exp">Gemini 2.0 Flash</SelectItem>
                        <SelectItem value="gemini-1.5-pro">Gemini 1.5 Pro</SelectItem>
                        <SelectItem value="gemini-1.5-flash">Gemini 1.5 Flash</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="temperature">Temperature</Label>
                    <Input
                      id="temperature"
                      type="number"
                      min="0"
                      max="2"
                      step="0.1"
                      value={editedStep.config.temperature || 0.7}
                      onChange={(e) => updateConfig('temperature', parseFloat(e.target.value))}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="maxTokens">Max Tokens</Label>
                  <Input
                    id="maxTokens"
                    type="number"
                    value={editedStep.config.maxTokens || 2048}
                    onChange={(e) => updateConfig('maxTokens', parseInt(e.target.value))}
                  />
                </div>
              </>
            )}

            {editedStep.type === 'tool' && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="toolName">Tool Name</Label>
                  <Input
                    id="toolName"
                    value={editedStep.config.toolName || ''}
                    onChange={(e) => updateConfig('toolName', e.target.value)}
                    placeholder="e.g., ragRetrieval, search"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="parameters">Parameters (JSON)</Label>
                  <Textarea
                    id="parameters"
                    value={JSON.stringify(editedStep.config.parameters || {}, null, 2)}
                    onChange={(e) => {
                      try {
                        const params = JSON.parse(e.target.value);
                        updateConfig('parameters', params);
                      } catch (err) {
                        // Invalid JSON, don't update
                      }
                    }}
                    placeholder='{"key": "value"}'
                    rows={6}
                    className="font-mono text-sm"
                  />
                </div>
              </>
            )}

            {editedStep.type === 'condition' && (
              <div className="space-y-2">
                <Label htmlFor="expression">Condition Expression</Label>
                <Textarea
                  id="expression"
                  value={editedStep.config.expression || ''}
                  onChange={(e) => updateConfig('expression', e.target.value)}
                  placeholder="input.userType === 'premium'"
                  rows={3}
                  className="font-mono text-sm"
                />
                <p className="text-xs text-muted-foreground">
                  JavaScript-like expression (e.g., input.field === 'value')
                </p>
              </div>
            )}

            {editedStep.type === 'loop' && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="iterateOver">Iterate Over</Label>
                  <Input
                    id="iterateOver"
                    value={editedStep.config.iterateOver || ''}
                    onChange={(e) => updateConfig('iterateOver', e.target.value)}
                    placeholder="items"
                  />
                  <p className="text-xs text-muted-foreground">
                    Variable name containing the array to loop over
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="maxIterations">Max Iterations</Label>
                  <Input
                    id="maxIterations"
                    type="number"
                    value={editedStep.config.maxIterations || 10}
                    onChange={(e) => updateConfig('maxIterations', parseInt(e.target.value))}
                  />
                </div>
              </>
            )}
          </TabsContent>

          {/* Advanced Tab */}
          <TabsContent value="advanced" className="space-y-4">
            <Card className="p-4 space-y-4">
              <h3 className="font-semibold">Error Handling</h3>

              <div className="flex items-center justify-between">
                <Label htmlFor="continueOnError">Continue on Error</Label>
                <Switch
                  id="continueOnError"
                  checked={editedStep.errorHandling?.continueOnError || false}
                  onCheckedChange={(checked) => updateErrorHandling('continueOnError', checked)}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="retries">Retries</Label>
                <Input
                  id="retries"
                  type="number"
                  min="0"
                  max="5"
                  value={editedStep.errorHandling?.retries || 0}
                  onChange={(e) => updateErrorHandling('retries', parseInt(e.target.value))}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="fallback">Fallback Step ID</Label>
                <Input
                  id="fallback"
                  value={editedStep.errorHandling?.fallback || ''}
                  onChange={(e) => updateErrorHandling('fallback', e.target.value)}
                  placeholder="step_fallback"
                />
              </div>
            </Card>

            <Card className="p-4 space-y-4">
              <h3 className="font-semibold">Conditional Execution</h3>

              <div className="space-y-2">
                <Label htmlFor="conditionExpr">Condition Expression</Label>
                <Textarea
                  id="conditionExpr"
                  value={editedStep.condition?.expression || ''}
                  onChange={(e) => updateCondition('expression', e.target.value)}
                  placeholder="input.shouldExecute === true"
                  rows={2}
                  className="font-mono text-sm"
                />
              </div>
            </Card>
          </TabsContent>

          {/* Mapping Tab */}
          <TabsContent value="mapping" className="space-y-4">
            <Card className="p-4 space-y-4">
              <h3 className="font-semibold">Input Mapping</h3>
              <p className="text-sm text-muted-foreground">
                Map context variables to step inputs
              </p>
              <Textarea
                value={JSON.stringify(editedStep.contextMapping?.input || {}, null, 2)}
                onChange={(e) => {
                  try {
                    const mapping = JSON.parse(e.target.value);
                    setEditedStep((prev) => ({
                      ...prev,
                      contextMapping: {
                        ...prev.contextMapping,
                        input: mapping,
                      },
                    }));
                  } catch (err) {
                    // Invalid JSON
                  }
                }}
                placeholder='{"stepInput": "contextVariable"}'
                rows={4}
                className="font-mono text-sm"
              />
            </Card>

            <Card className="p-4 space-y-4">
              <h3 className="font-semibold">Output Mapping</h3>
              <p className="text-sm text-muted-foreground">
                Map step outputs to context variables
              </p>
              <Textarea
                value={JSON.stringify(editedStep.contextMapping?.output || {}, null, 2)}
                onChange={(e) => {
                  try {
                    const mapping = JSON.parse(e.target.value);
                    setEditedStep((prev) => ({
                      ...prev,
                      contextMapping: {
                        ...prev.contextMapping,
                        output: mapping,
                      },
                    }));
                  } catch (err) {
                    // Invalid JSON
                  }
                }}
                placeholder='{"stepOutput": "contextVariable"}'
                rows={4}
                className="font-mono text-sm"
              />
            </Card>
          </TabsContent>
        </Tabs>

        {/* Actions */}
        <div className="mt-6 flex justify-end gap-2">
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleSave}>
            <Save className="w-4 h-4 mr-2" />
            Save Changes
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}
"}

{"file_path": "src/components/admin/flow-builder/ExecutionTraceViewer.tsx", "initial_content": "/**
 * Execution Trace Viewer
 * Week 3 - Day 2: Trace Viewer
 * 
 * View detailed execution traces with step-by-step breakdown
 */

'use client';

import React, { useState } from 'react';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  CheckCircle2,
  XCircle,
  Clock,
  AlertCircle,
  ChevronDown,
  ChevronRight,
  Copy,
} from 'lucide-react';
import type { ExecutionTrace, StepTrace } from '@/services/execution-trace-service';

// ============================================================================
// Execution Trace Viewer Component
// ============================================================================

interface ExecutionTraceViewerProps {
  trace: ExecutionTrace;
}

export function ExecutionTraceViewer({ trace }: ExecutionTraceViewerProps) {
  const [expandedSteps, setExpandedSteps] = useState<Set<string>>(new Set());

  const toggleStep = (stepId: string) => {
    setExpandedSteps((prev) => {
      const next = new Set(prev);
      if (next.has(stepId)) {
        next.delete(stepId);
      } else {
        next.add(stepId);
      }
      return next;
    });
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'success':
        return <CheckCircle2 className="w-4 h-4 text-green-500" />;
      case 'error':
        return <XCircle className="w-4 h-4 text-red-500" />;
      case 'running':
        return <Clock className="w-4 h-4 text-blue-500 animate-spin" />;
      case 'skipped':
        return <AlertCircle className="w-4 h-4 text-yellow-500" />;
      default:
        return null;
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'destructive' | 'secondary'> = {
      success: 'default',
      error: 'destructive',
      running: 'secondary',
      skipped: 'secondary',
    };

    return (
      <Badge variant={variants[status] || 'secondary'}>
        {status}
      </Badge>
    );
  };

  const formatDuration = (ms: number) => {
    if (ms < 1000) return `${ms}ms`;
    return `${(ms / 1000).toFixed(2)}s`;
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <Card className="p-4">
        <div className="flex items-start justify-between">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <h2 className="text-lg font-semibold">Execution Trace</h2>
              {getStatusBadge(trace.status)}
            </div>
            <p className="text-sm text-muted-foreground">
              Trace ID: {trace.id}
            </p>
            <p className="text-sm text-muted-foreground">
              Flow: {trace.flowId} v{trace.flowVersion}
            </p>
          </div>

          <div className="text-right text-sm">
            <p className="text-muted-foreground">
              Started: {new Date(trace.startTime).toLocaleString()}
            </p>
            {trace.endTime && (
              <p className="text-muted-foreground">
                Ended: {new Date(trace.endTime).toLocaleString()}
              </p>
            )}
            {trace.duration && (
              <p className="font-medium">
                Duration: {formatDuration(trace.duration)}
              </p>
            )}
          </div>
        </div>
      </Card>

      {/* Metrics */}
      <div className="grid grid-cols-4 gap-4">
        <Card className="p-4">
          <p className="text-sm text-muted-foreground">Total Tokens</p>
          <p className="text-2xl font-bold">{trace.metrics.totalTokens.toLocaleString()}</p>
        </Card>
        <Card className="p-4">
          <p className="text-sm text-muted-foreground">Total Cost</p>
          <p className="text-2xl font-bold">${trace.metrics.totalCost.toFixed(4)}</p>
        </Card>
        <Card className="p-4">
          <p className="text-sm text-muted-foreground">Cache Hits</p>
          <p className="text-2xl font-bold">{trace.metrics.cacheHits}</p>
        </Card>
        <Card className="p-4">
          <p className="text-sm text-muted-foreground">Cache Misses</p>
          <p className="text-2xl font-bold">{trace.metrics.cacheMisses}</p>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs defaultValue="steps" className="w-full">
        <TabsList>
          <TabsTrigger value="steps">Steps ({trace.steps.length})</TabsTrigger>
          <TabsTrigger value="input">Input</TabsTrigger>
          <TabsTrigger value="output">Output</TabsTrigger>
          <TabsTrigger value="context">Context</TabsTrigger>
          {trace.error && <TabsTrigger value="error">Error</TabsTrigger>}
        </TabsList>

        {/* Steps Tab */}
        <TabsContent value="steps">
          <ScrollArea className="h-[600px]">
            <div className="space-y-2">
              {trace.steps.map((step, index) => (
                <StepTraceCard
                  key={step.stepId}
                  step={step}
                  index={index}
                  expanded={expandedSteps.has(step.stepId)}
                  onToggle={() => toggleStep(step.stepId)}
                />
              ))}

              {trace.steps.length === 0 && (
                <Card className="p-8 text-center text-muted-foreground">
                  No steps recorded yet
                </Card>
              )}
            </div>
          </ScrollArea>
        </TabsContent>

        {/* Input Tab */}
        <TabsContent value="input">
          <Card className="p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold">Input Data</h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => copyToClipboard(JSON.stringify(trace.input, null, 2))}
              >
                <Copy className="w-4 h-4 mr-2" />
                Copy
              </Button>
            </div>
            <pre className="bg-muted p-4 rounded-lg overflow-x-auto text-sm">
              {JSON.stringify(trace.input, null, 2)}
            </pre>
          </Card>
        </TabsContent>

        {/* Output Tab */}
        <TabsContent value="output">
          <Card className="p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold">Output Data</h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => copyToClipboard(JSON.stringify(trace.output, null, 2))}
              >
                <Copy className="w-4 h-4 mr-2" />
                Copy
              </Button>
            </div>
            {trace.output ? (
              <pre className="bg-muted p-4 rounded-lg overflow-x-auto text-sm">
                {JSON.stringify(trace.output, null, 2)}
              </pre>
            ) : (
              <p className="text-muted-foreground text-center py-8">No output available</p>
            )}
          </Card>
        </TabsContent>

        {/* Context Tab */}
        <TabsContent value="context">
          <Card className="p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold">Execution Context</h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => copyToClipboard(JSON.stringify(trace.context, null, 2))}
              >
                <Copy className="w-4 h-4 mr-2" />
                Copy
              </Button>
            </div>
            <pre className="bg-muted p-4 rounded-lg overflow-x-auto text-sm">
              {JSON.stringify(trace.context, null, 2)}
            </pre>
          </Card>
        </TabsContent>

        {/* Error Tab */}
        {trace.error && (
          <TabsContent value="error">
            <Card className="p-4 border-red-200 bg-red-50 dark:bg-red-950/20">
              <h3 className="font-semibold text-red-600 dark:text-red-400 mb-4">
                Error Details
              </h3>
              <div className="space-y-2">
                <p className="text-sm">
                  <span className="font-medium">Message:</span> {trace.error.message}
                </p>
                {trace.error.name && (
                  <p className="text-sm">
                    <span className="font-medium">Type:</span> {trace.error.name}
                  </p>
                )}
                {trace.error.stack && (
                  <div className="mt-4">
                    <p className="font-medium text-sm mb-2">Stack Trace:</p>
                    <pre className="bg-muted p-4 rounded-lg overflow-x-auto text-xs">
                      {trace.error.stack}
                    </pre>
                  </div>
                )}
              </div>
            </Card>
          </TabsContent>
        )}
      </Tabs>
    </div>
  );
}

// ============================================================================
// Step Trace Card Component
// ============================================================================

interface StepTraceCardProps {
  step: StepTrace;
  index: number;
  expanded: boolean;
  onToggle: () => void;
}

function StepTraceCard({ step, index, expanded, onToggle }: StepTraceCardProps) {
  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'success':
        return <CheckCircle2 className="w-5 h-5 text-green-500" />;
      case 'error':
        return <XCircle className="w-5 h-5 text-red-500" />;
      case 'skipped':
        return <AlertCircle className="w-5 h-5 text-yellow-500" />;
      default:
        return null;
    }
  };

  const formatDuration = (ms: number) => {
    if (ms < 1000) return `${ms}ms`;
    return `${(ms / 1000).toFixed(2)}s`;
  };

  return (
    <Card className="p-4">
      <div
        className="flex items-start justify-between cursor-pointer"
        onClick={onToggle}
      >
        <div className="flex items-start gap-3 flex-1">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-muted-foreground">
              #{index + 1}
            </span>
            {getStatusIcon(step.status)}
          </div>

          <div className="flex-1">
            <h4 className="font-medium">{step.stepName}</h4>
            <p className="text-sm text-muted-foreground">ID: {step.stepId}</p>
            <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground">
              <span>Duration: {formatDuration(step.duration)}</span>
              {step.metrics?.tokens && (
                <span>Tokens: {step.metrics.tokens}</span>
              )}
              {step.metrics?.cost && (
                <span>Cost: ${step.metrics.cost.toFixed(4)}</span>
              )}
            </div>
          </div>
        </div>

        <Button variant="ghost" size="sm">
          {expanded ? (
            <ChevronDown className="w-4 h-4" />
          ) : (
            <ChevronRight className="w-4 h-4" />
          )}
        </Button>
      </div>

      {expanded && (
        <div className="mt-4 space-y-4 border-t pt-4">
          {step.input && (
            <div>
              <p className="text-sm font-medium mb-2">Input:</p>
              <pre className="bg-muted p-3 rounded text-xs overflow-x-auto">
                {JSON.stringify(step.input, null, 2)}
              </pre>
            </div>
          )}

          {step.output && (
            <div>
              <p className="text-sm font-medium mb-2">Output:</p>
              <pre className="bg-muted p-3 rounded text-xs overflow-x-auto">
                {JSON.stringify(step.output, null, 2)}
              </pre>
            </div>
          )}

          {step.error && (
            <div className="bg-red-50 dark:bg-red-950/20 p-3 rounded">
              <p className="text-sm font-medium text-red-600 dark:text-red-400 mb-2">
                Error:
              </p>
              <p className="text-sm">{step.error.message || String(step.error)}</p>
            </div>
          )}

          {step.metrics && (
            <div>
              <p className="text-sm font-medium mb-2">Metrics:</p>
              <div className="grid grid-cols-2 gap-2 text-sm">
                {Object.entries(step.metrics).map(([key, value]) => (
                  <div key={key} className="flex justify-between">
                    <span className="text-muted-foreground">{key}:</span>
                    <span className="font-medium">{String(value)}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </Card>
  );
}
"}

