import type { FlowConfiguration } from '@/lib/models/flow-config';

// ============================================================================
// Flow List Page Component
// ============================================================================

interface FlowListPageProps {
  onCreateNew?: () => void;
  onEdit?: (flow: FlowConfiguration) => void;
  onExecute?: (flow: FlowConfiguration) => void;
  onViewStats?: (flow: FlowConfiguration) => void;
  onDelete?: (flow: FlowConfiguration) => void;
}

export function FlowListPage({
  onCreateNew,
  onEdit,
  onExecute,
  onViewStats,
  onDelete,
}: FlowListPageProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [currentPage, setCurrentPage] = useState(0);
  const [pageSize] = useState(20);

  // Fetch flows
  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ['flows', statusFilter, categoryFilter, searchQuery, currentPage],
    queryFn: async () => {
      const params = new URLSearchParams({
        limit: pageSize.toString(),
        offset: (currentPage * pageSize).toString(),
      });

      if (statusFilter !== 'all') {
        params.append('status', statusFilter);
      }

      if (categoryFilter !== 'all') {
        params.append('category', categoryFilter);
      }

      if (searchQuery) {
        params.append('search', searchQuery);
      }

      const response = await fetch(`/api/admin/flows?${params}`);
      if (!response.ok) throw new Error('Failed to fetch flows');
      return response.json();
    },
  });

  const flows = data?.flows || [];
  const total = data?.total || 0;
  const hasMore = data?.hasMore || false;

  const handleSearch = (value: string) => {
    setSearchQuery(value);
    setCurrentPage(0);
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive'> = {
      active: 'default',
      draft: 'secondary',
      deprecated: 'destructive',
    };

    return (
      <Badge variant={variants[status] || 'secondary'}>
        {status}
      </Badge>
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Flows</h1>
          <p className="text-muted-foreground">
            Manage and monitor your dynamic flows
          </p>
        </div>
        <Button onClick={onCreateNew}>
          <Plus className="w-4 h-4 mr-2" />
          Create Flow
        </Button>
      </div>

      {/* Filters */}
      <Card className="p-4">
        <div className="flex flex-col md:flex-row gap-4">
          {/* Search */}
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Search flows..."
              value={searchQuery}
              onChange={(e) => handleSearch(e.target.value)}
              className="pl-9"
            />
          </div>

          {/* Status Filter */}
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[180px]">
              <Filter className="w-4 h-4 mr-2" />
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="active">Active</SelectItem>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="deprecated">Deprecated</SelectItem>
            </SelectContent>
          </Select>

          {/* Category Filter */}
          <Select value={categoryFilter} onValueChange={setCategoryFilter}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              <SelectItem value="content-generation">Content Generation</SelectItem>
              <SelectItem value="analysis">Analysis</SelectItem>
              <SelectItem value="automation">Automation</SelectItem>
              <SelectItem value="research">Research</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Results count */}
        <div className="mt-4 text-sm text-muted-foreground">
          Showing {flows.length} of {total} flows
        </div>
      </Card>

      {/* Table */}
      <Card>
        {isLoading ? (
          <div className="p-8 text-center">
            <p className="text-muted-foreground">Loading flows...</p>
          </div>
        ) : error ? (
          <div className="p-8 text-center">
            <p className="text-red-500">Error loading flows</p>
            <Button variant="outline" onClick={() => refetch()} className="mt-4">
              Retry
            </Button>
          </div>
        ) : flows.length === 0 ? (
          <div className="p-8 text-center">
            <p className="text-muted-foreground mb-4">No flows found</p>
            <Button onClick={onCreateNew}>
              <Plus className="w-4 h-4 mr-2" />
              Create Your First Flow
            </Button>
          </div>
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Version</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Category</TableHead>
                  <TableHead>Steps</TableHead>
                  <TableHead>Updated</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {flows.map((flow: FlowConfiguration) => (
                  <TableRow key={flow.id}>
                    <TableCell className="font-medium">
                      <div>
                        <p>{flow.name}</p>
                        {flow.description && (
                          <p className="text-xs text-muted-foreground mt-1">
                            {flow.description.substring(0, 60)}
                            {flow.description.length > 60 && '...'}
                          </p>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{flow.version}</Badge>
                    </TableCell>
                    <TableCell>{getStatusBadge(flow.status)}</TableCell>
                    <TableCell>
                      {flow.category ? (
                        <Badge variant="secondary">{flow.category}</Badge>
                      ) : (
                        <span className="text-muted-foreground">-</span>
                      )}
                    </TableCell>
                    <TableCell>{flow.steps.length}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {new Date(flow.updatedAt).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="sm">
                            <MoreHorizontal className="w-4 h-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuLabel>Actions</DropdownMenuLabel>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => onEdit?.(flow)}>
                            <Edit className="w-4 h-4 mr-2" />
                            Edit
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => onExecute?.(flow)}>
                            <Play className="w-4 h-4 mr-2" />
                            Execute
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => onViewStats?.(flow)}>
                            <BarChart3 className="w-4 h-4 mr-2" />
                            View Stats
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem>
                            <Copy className="w-4 h-4 mr-2" />
                            Clone
                          </DropdownMenuItem>
                          <DropdownMenuItem>
                            <Eye className="w-4 h-4 mr-2" />
                            View Details
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem
                            onClick={() => onDelete?.(flow)}
                            className="text-red-600"
                          >
                            <Trash2 className="w-4 h-4 mr-2" />
                            Delete
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>

            {/* Pagination */}
            {total > pageSize && (
              <div className="p-4 border-t flex items-center justify-between">
                <p className="text-sm text-muted-foreground">
                  Page {currentPage + 1} of {Math.ceil(total / pageSize)}
                </p>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage((p) => Math.max(0, p - 1))}
                    disabled={currentPage === 0}
                  >
                    Previous
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage((p) => p + 1)}
                    disabled={!hasMore}
                  >
                    Next
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </Card>
    </div>
  );
}
"}

{"file_path": "src/app/admin/flow-builder/page.tsx", "initial_content": "/**
 * Flow Builder Admin Page
 * Week 3 - Day 3: Main Admin Page
 */

'use client';

import React, { useState } from 'react';
import { FlowBuilderCanvas } from '@/components/admin/flow-builder/FlowBuilderCanvas';
import { FlowListPage } from '@/components/admin/flow-builder/FlowListPage';
import { ExecutionTraceViewer } from '@/components/admin/flow-builder/ExecutionTraceViewer';
import { FlowStatsDashboard } from '@/components/admin/flow-builder/FlowStatsDashboard';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useQuery } from '@tanstack/react-query';
import type { FlowConfiguration } from '@/lib/models/flow-config';
import type { ExecutionTrace } from '@/services/execution-trace-service';

export default function FlowBuilderPage() {
  const [selectedFlow, setSelectedFlow] = useState<FlowConfiguration | null>(null);
  const [selectedTrace, setSelectedTrace] = useState<ExecutionTrace | null>(null);
  const [activeTab, setActiveTab] = useState('list');

  // Fetch analytics for selected flow
  const { data: analytics } = useQuery({
    queryKey: ['flow-analytics', selectedFlow?.id],
    queryFn: async () => {
      if (!selectedFlow) return null;
      const response = await fetch(`/api/admin/flows/${selectedFlow.id}/analytics`);
      if (!response.ok) return null;
      return response.json();
    },
    enabled: !!selectedFlow && activeTab === 'stats',
  });

  const handleCreateNew = () => {
    setSelectedFlow({
      id: `flow_${Date.now()}`,
      name: 'New Flow',
      description: '',
      version: '1.0.0',
      tags: [],
      status: 'draft',
      inputSchema: {},
      outputSchema: {},
      steps: [],
      config: {},
      createdAt: new Date(),
      updatedAt: new Date(),
    });
    setActiveTab('builder');
  };

  const handleEdit = (flow: FlowConfiguration) => {
    setSelectedFlow(flow);
    setActiveTab('builder');
  };

  const handleExecute = async (flow: FlowConfiguration) => {
    try {
      // TODO: Show input dialog
      const input = { test: 'input' };

      const response = await fetch('/api/admin/flows/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          flowId: flow.id,
          flowVersion: flow.version,
          input,
        }),
      });

      const result = await response.json();

      if (result.success && result.traceId) {
        // Fetch the trace
        const traceResponse = await fetch(`/api/admin/traces/${result.traceId}`);
        const traceData = await traceResponse.json();
        setSelectedTrace(traceData.trace);
        setActiveTab('traces');
      }
    } catch (error) {
      console.error('Failed to execute flow:', error);
    }
  };

  const handleViewStats = (flow: FlowConfiguration) => {
    setSelectedFlow(flow);
    setActiveTab('stats');
  };

  const handleSave = async (config: FlowConfiguration) => {
    try {
      const response = await fetch(`/api/admin/flows/${config.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config),
      });

      if (response.ok) {
        alert('Flow saved successfully!');
      }
    } catch (error) {
      console.error('Failed to save flow:', error);
      alert('Failed to save flow');
    }
  };

  return (
    <div className="container mx-auto py-6">
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="list">Flows</TabsTrigger>
          <TabsTrigger value="builder">Builder</TabsTrigger>
          <TabsTrigger value="traces">Traces</TabsTrigger>
          <TabsTrigger value="stats">Analytics</TabsTrigger>
        </TabsList>

        <TabsContent value="list" className="mt-6">
          <FlowListPage
            onCreateNew={handleCreateNew}
            onEdit={handleEdit}
            onExecute={handleExecute}
            onViewStats={handleViewStats}
          />
        </TabsContent>

        <TabsContent value="builder" className="mt-6 h-[800px]">
          {selectedFlow ? (
            <FlowBuilderCanvas
              flowConfig={selectedFlow}
              onSave={handleSave}
              onExecute={handleExecute}
            />
          ) : (
            <div className="text-center p-8">
              <p className="text-muted-foreground">
                Select a flow to edit or create a new one
              </p>
            </div>
          )}
        </TabsContent>

        <TabsContent value="traces" className="mt-6">
          {selectedTrace ? (
            <ExecutionTraceViewer trace={selectedTrace} />
          ) : (
            <div className="text-center p-8">
              <p className="text-muted-foreground">
                Execute a flow to view its trace
              </p>
            </div>
          )}
        </TabsContent>

        <TabsContent value="stats" className="mt-6">
          {selectedFlow && analytics ? (
            <FlowStatsDashboard analytics={analytics} />
          ) : (
            <div className="text-center p-8">
              <p className="text-muted-foreground">
                Select a flow to view its analytics
              </p>
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}
"}

